// ── HANDLEIDING ──────────────────────────────────────────────────────────
// Eén pagina, maar toont sinds 25 juli 2026 (op Marcels verzoek) uitsluitend de sectie die bij de
// rol van de ingelogde gebruiker hoort — een verkoper ziet dus geen begeleider-/koperinhoud en
// omgekeerd. Vóór deze wijziging kreeg iedereen alle vier de secties te zien; dat bleek onnodige
// ruis te geven en zonder onderscheid tussen partijen. Bereikbaar via de "Handleiding"-link in het
// dashboard, en rechtstreeks via mna.html?code=XXXX&screen=handleiding (bijv. vanuit de
// uitnodigingsmail). Werkregel (Marcel, 25 juli 2026): bij elke gebruikersgerichte wijziging aan
// het platform hoort deze pagina in dezelfde wijziging bijgewerkt te worden — zie CLAUDE.md.
function renderHandleiding(){
  var terugScherm = isTussen() ? 'begeleider' : 'main';
  var html = '<div class="wrap anim"><div class="hdr"><div class="brand">'+brandMerkHtml()+BRAND.platform+' &middot; Handleiding</div>'
    + '<button class="btn-ghost btn-sm" onclick="S.screen=\''+terugScherm+'\';renderApp()">&#8592; Terug naar dashboard</button></div>';

  html += '<div style="font-family:Playfair Display,serif;font-size:1.5rem;color:var(--head);font-weight:600;margin-bottom:.25rem">Handleiding '+esc(BRAND.platform)+'</div>';

  // data-hb-sectie / data-hb-item: markeringen voor het zoekveld (hbZoek hieronder) — de filtering
  // leunt daardoor niet op stijl. Een stap krijgt een eigen wrapper zonder display-stijl, zodat het
  // hidden-attribuut niet door de inline display:flex wordt overschreven.
  function sectie(id, titel, inhoud){
    return '<div id="hl-'+id+'" class="panel" data-hb-sectie style="margin-bottom:1.5rem">'
      + '<div style="font-family:Playfair Display,serif;font-size:1.2rem;color:var(--head);font-weight:600;margin-bottom:1rem">'+titel+'</div>'
      + inhoud + '</div>';
  }
  function stap(nr, titel, tekst){
    return '<div data-hb-item><div style="display:flex;gap:12px;margin-bottom:1rem;align-items:flex-start">'
      + '<div style="flex-shrink:0;width:26px;height:26px;border-radius:50%;background:var(--teal-bg);color:var(--teal);font-weight:700;font-size:12px;display:flex;align-items:center;justify-content:center">'+nr+'</div>'
      + '<div><div style="font-weight:600;color:var(--head);font-size:13px;margin-bottom:.2rem">'+titel+'</div><div style="font-size:13px;color:var(--mid);line-height:1.65">'+tekst+'</div></div>'
      + '</div></div>';
  }

  // Productpunt 31 (15 okt 2026): zoekveld bovenaan. Filtert alleen wat hieronder al gerenderd is;
  // de secties van andere rollen worden niet gerenderd en kunnen dus ook via zoeken nooit verschijnen.
  html += '<div data-hb-root>'
    + '<label for="hb-zoek" style="display:block;font-weight:600;color:var(--head);font-size:13px;margin:.75rem 0 .3rem">Zoek in de handleiding</label>'
    + '<input id="hb-zoek" type="search" autocomplete="off" oninput="hbZoek(this)" style="width:100%;box-sizing:border-box;margin-bottom:1rem">'
    + '<div data-hb-leeg role="status" hidden style="font-size:13px;color:var(--mid);margin-bottom:1rem"></div>';

  var eigenRol = isKoper() ? 'koper' : isTussen() ? 'begeleider' : 'verkoper';

  var secties = {};
  secties.verkoper = sectie('verkoper', '👤 Verkoper', ''
    + stap(1,'Inloggen','U logt in op <code>mna.html</code> met uw persoonlijke <strong>verkopercode</strong> (van uw adviseur ontvangen). Deze code is persoonlijk — deel hem niet met derden.')
    + stap(2,'Eenmalig openingsscherm (alleen bij een nieuw traject)','Bij de allereerste keer inloggen op een nieuw traject vraagt het platform eerst een paar basisgegevens: het adres en KvK-nummer van uw onderneming, en de naam van de tekenbevoegde. Heeft uw onderneming een holdingstructuur met werkmaatschappijen, of meerdere partners? Dan registreert u die hier ook meteen (beide zijn optioneel — geen groepsstructuur of maar één eigenaar? Dan slaat u dat onderdeel gewoon over). Dit is eenmalig; bij elke volgende keer inloggen gaat u direct door naar het gewone dossier. Bestaande trajecten die al liepen vóór deze functie is ingevoerd, krijgen dit scherm niet te zien.')
    + stap('2a','Uw route: de M&amp;A Journey','Op uw startscherm ziet u de veertien fasen van het traject en waar het traject nu staat. Taken voor u zijn gemarkeerd met Uw taak, bijvoorbeeld gegevens invullen, de gewenste transactievorm kiezen of het informatiememorandum beoordelen. Met Uitvoeren gaat u direct naar het juiste scherm. Interne stukken van uw adviseur, zoals het dealvoorstel, ziet u hier niet.')
    + stap('2b','Shortlist beoordelen','Legt uw adviseur een shortlist aan u voor, dan ziet u op uw startscherm het blok Shortlist ter beoordeling. Per kandidaat ziet u de matchscore, de score per criterium en het advies van uw adviseur. Per kandidaat kiest u Akkoord of Niet doorgaan, eventueel met een toelichting. Uw besluit wordt met datum vastgelegd en kan daarna niet meer worden gewijzigd; uw adviseur ziet het direct.')
    + stap(3,'De 7 informatiefases doorlopen — zelf invullen, of documenten laten uitlezen','U kunt de velden hieronder zelf invullen, of eerst uw documenten uploaden (fase 4 hieronder) en automatisch laten invullen — beide kan, in elke volgorde. Documenten dienen ook als onderbouwing bij het dossier. Automatisch invullen door AI is bij uploaden een bewuste keuze (het vinkje "alleen als bewijsstuk"), geen verplichting. Het dossier is verdeeld in 7 fases: Financieel, Klanten &amp; commercieel, Partners &amp; personeel, Compliance &amp; kwaliteit, IT &amp; automatisering, Juridisch &amp; fiscaal, Strategisch &amp; markt. Boven elke fase staat een korte toelichting wat er in die fase precies gevraagd wordt en waarom dat relevant is. Fase 2-velden (aanvullende, diepere vragen) worden pas zichtbaar ná ondertekening van de LoI — dat is bewust zo, niet een fout in het scherm. Binnen fase 2 van "Financieel" staat een blok "— Balans &amp; schuld" (nettoresultaat, eigen vermogen, balanstotaal, liquide middelen, kortlopende/langlopende schulden, rentelasten, aflossingsverplichting) — deze velden zijn niet verplicht, maar voeden wel de financiële ratio\'s (solvabiliteit, ROE, ROA, current/quick ratio, DSCR, netto schuld/EBITDA) die daarna op het waarderingsscherm verschijnen. Een ratio verschijnt alleen als de bijbehorende velden zijn ingevuld — ontbrekende data geeft geen 0%, die ratio blijft dan gewoon weg. In fase 1 van "Partners &amp; personeel" vraagt het platform ook naar de managementlaag onder de eigenaar/partners (het tweede echelon) en naar de mate waarin omzet of klantrelaties van één persoon afhangen; eventuele aanblijf-/retentieafspraken voor management komen in fase 2 aan bod. Deze punten wegen mee in de risico-inschatting en het dealvoorstel.')
    + stap(4,'Documenten uploaden — als bewijsstuk, of laten uitlezen door AI','Upload rechts bij elke fase de relevante documenten (jaarrekeningen, KvK-uittreksel, contracten, e.d.). U kiest zelf per upload: <strong>"Alleen als bewijsstuk toevoegen (geen AI-analyse)"</strong> aangevinkt &mdash; het document wordt alleen bewaard als onderbouwing, er verandert niets aan uw ingevulde velden (herkenbaar aan het label "📎 Bewijsstuk" in de documentenlijst). Niet aangevinkt (standaard) &mdash; de AI leest het document en vult ontbrekende velden automatisch aan. Een veld dat u zelf al heeft ingevuld wordt nooit automatisch overschreven; bij de belangrijkste financiële velden (zoals omzet en EBITDA) krijgt u bij een afwijkende waarde uit een document ook een keuzescherm om zelf de juiste waarde aan te wijzen. Ondersteunde bestandstypen: PDF, Word, Excel/CSV, tekst, en <strong>SBR/XBRL-jaarrekeningen</strong> (.xml/.xbrl) — die laatste worden 100% deterministisch uitgelezen, zonder AI, rechtstreeks uit de officiële XBRL-tags. Let op: bij kleine/middelgrote rechtspersonen bevat een SBR-bestand wettelijk geen apart omzetcijfer (pas vanaf brutomarge) — dat is een wettelijke beperking, geen fout. Heeft u een geüpload document later gecorrigeerd (bijv. een herziene jaarrekening)? Gebruik dan de knop "↻ Vervangen" naast dat document — de nieuwe versie komt zo in dezelfde keten te staan (herkenbaar aan het v2/v3-label), en via "🕒 Versies" is de volledige geschiedenis met downloadlinks terug te vinden. <strong>Status per document:</strong> in de documentenlijst staat bij elk nieuw geüpload document wat er werkelijk mee is gebeurd — "Geanalyseerd" (velden zijn automatisch aangevuld), "Opgeslagen, niet geanalyseerd" (bij een bewijsstuk het label "📎 Bewijsstuk"), "Controle nodig" of "Mislukt", met de reden eronder. Alleen bij "Geanalyseerd" worden gegevens uit het document overgenomen; bij "Controle nodig" of "Mislukt" niet. Deze status blijft ook na opnieuw laden zichtbaar; een downloadlink staat er alleen als het bestand echt is opgeslagen. Mislukt een vervanging of vraagt die om controle, dan blijft de vorige versie gewoon staan. Kon de server niet (op tijd) antwoorden, dan meldt het scherm dat de uitkomst onbekend is en laadt het de lijst opnieuw — controleer die lijst voordat u het bestand nog eens uploadt; er wordt nooit automatisch opnieuw geüpload. Kon de documentenlijst zelf niet geladen worden, dan ziet u een melding met "Opnieuw laden" in plaats van een lege lijst. <strong>Meerdere bestanden tegelijk</strong> worden één voor één verwerkt; een fout bij één bestand houdt de volgende niet tegen. Na afloop ziet u per bestand de uitkomst en een telling (aangeboden, geanalyseerd, opgeslagen zonder analyse, controle nodig, mislukt, niet aangeboden). Met "Annuleer resterende bestanden" stopt u alleen de bestanden die nog niet zijn verstuurd; het bestand dat op dat moment wordt verwerkt loopt door, en een al verstuurd bestand wordt nooit verwijderd.')
    + stap('4b','Kolommenbalans inlezen','In de fase Financieel kunt u per afgesloten boekjaar de kolommenbalans (de saldibalans per grootboekrekening) inlezen als CSV- of Excel-export uit uw boekhoudpakket. Het platform deelt de rekeningen in en maakt er een exploitatieoverzicht van (omzet, kosten, EBITDA, resultaat). Rekeningen die niet eenduidig in te delen zijn, wijst uw adviseur toe. Een bestand met onduidelijke bedragen wordt niet ingelezen; controleer dan de export. Staat de kolommenbalans al in het dossier omdat u hem met de andere documenten heeft geüpload, dan ziet u hem bovenaan het blok onder In het dossier gevonden. Controleer het boekjaar (voorgesteld uit de bestandsnaam) en kies Inlezen als kolommenbalans; opnieuw uploaden is niet nodig.')
    + stap('4b2','Bankafschriften inlezen','In de fase Financieel leest u onder Bankmutaties uw bankafschriften in: als CSV-export, MT940 (.sta of .940) of CAMT.053 (XML). Heeft u de afschriften al met de andere documenten geüpload, dan staan ze daar onder Bankafschriften in het dossier, nog niet ingelezen; met Inlezen als bankmutaties neemt u ze over zonder opnieuw te uploaden. Hetzelfde afschrift in een ander formaat wordt herkend: transacties die al zijn ingelezen (zelfde datum en bedrag) worden niet dubbel geteld, en u kiest dan om alleen de nieuwe transacties in te lezen.')
    + stap('4c','Normalisaties','Onder de kolommenbalans ziet u de genormaliseerde EBITDA: de gerapporteerde EBITDA plus of min de normalisaties die uw adviseur heeft goedgekeurd. U kunt zelf een normalisatie voorstellen (bijvoorbeeld een eenmalige uitgave of een afwijkende eigen beloning), met bedrag, boekjaar, bron en motivering. Een voorstel telt pas mee nadat uw adviseur het heeft goedgekeurd.')
    + stap(5,'Extra controle (optioneel)','Bij het uploaden staat ook een vinkje "Extra controle (dubbele AI-analyse)". Aangevinkt wordt het document twee keer onafhankelijk gelezen; komen de twee lezingen niet overeen, dan krijgt u een keuze in plaats van een gok. Kost iets meer tijd, daarom standaard uit — en gaat niet samen met "Alleen als bewijsstuk toevoegen" (dan vindt er sowieso geen AI-analyse plaats).')
    + stap(6,'Automatisch ingevulde waarden controleren','Elk automatisch ingevuld veld toont van welk document het afkomstig is ("uit: bestand.pdf") — hover voor het letterlijke citaat uit het document. Geeft een tweede document een andere waarde voor hetzelfde veld, dan verschijnt een keuzescherm ("Afwijkende waarden gevonden") waarin u zelf de juiste waarde aanwijst. Komen de twee waarden uit verschillende boekjaren (bijv. de EBITDA-marge uit het 2023- én het 2024-verslag), dan staat het boekjaar bij elke waarde vermeld en adviseert het scherm doorgaans het meest recente jaar te kiezen. Heeft de uitlezing aandachtspunten (bijv. een cijfer dat niet is overgenomen, een afwijkende bedrijfsnaam of een lagere AI-betrouwbaarheid), dan staan die als "⚠ Aandachtspunten bij &lt;bestand&gt;" na het uploaden direct onder dat document in de documentenlijst (tot u de pagina opnieuw laadt).')
    + stap('6b','Gewenste transactievorm','In de fase Strategisch &amp; markt geeft u aan hoe u de overdracht voor zich ziet: de juridische structuur (aandelen, activa-passiva, fusie, anders of nog onbekend), de omvang (volledig, een minderheidsbelang of gefaseerd, met het percentage), de betaling (direct, earn-out, vendor loan of gespreid, ook in combinatie) en of u hierover advies wenst. Uw keuzes worden automatisch opgeslagen; de knop onder het formulier slaat direct op. Is de invoer nog niet compleet wanneer u de fase verlaat, dan krijgt u daarvan een melding. Uw adviseur kan een ander advies en meerdere scenario\'s vastleggen; uw eigen voorkeur blijft daarbij altijd zichtbaar zoals u die heeft opgegeven. In het informatiememorandum wordt alleen uw voorkeur op hoofdlijnen genoemd.')
    + stap('6c','Het informatiememorandum beoordelen','Zodra uw adviseur het concept-informatiememorandum met u deelt, krijgt u een e-mail en staat het bovenaan uw dossier. Lees het per onderdeel na en plaats bij een onderdeel een opmerking over de tekst, cijfers, normalisaties, grafieken, foto\'s of de transactievorm. Aanvullende stukken uploadt u in de betreffende fase. Vraagt uw adviseur om extra informatie, dan reageert u direct bij die opmerking. Biedt uw adviseur daarna de bijgewerkte versie ter goedkeuring aan, dan geeft u akkoord op precies die versie, of u plaatst een nieuwe opmerking. Pas na uw akkoord kan het memorandum definitief worden vastgesteld. Definitief betekent nog niet dat het met kopers wordt gedeeld; dat gebeurt alleen met partijen die een geheimhoudingsverklaring hebben getekend.')
    + stap(7,'Meerdere bedrijfsonderdelen (groepsstructuur)','Bestaat uw onderneming uit een holding met werkmaatschappijen, dan ziet u bij het uploaden een keuzemenu om het document aan de juiste entiteit te koppelen. Herkent de AI de entiteit niet met zekerheid, dan wordt niets automatisch verwerkt — u koppelt het dan zelf handmatig via de dataroom. Entiteiten die u niet al bij het openingsscherm (stap 2) heeft ingevoerd, kunt u hier alsnog toevoegen.<br><br>Is het document een geconsolideerd stuk van de hele groep (bijvoorbeeld een geconsolideerde jaarrekening), kies dan bij het uploaden &lsquo;Groep (geconsolideerd document)&rsquo;; met &lsquo;Automatisch herkennen&rsquo; bepaalt de AI de entiteit. Een document met &lsquo;Handmatig koppelen&rsquo; kunt u in het koppelmenu ook op &lsquo;Groepsniveau (geconsolideerd)&rsquo; zetten. Wijkt een cijfer uit zo&rsquo;n groepsdocument af van de berekende som van de entiteiten, dan kiest u in het keuzevenster welke waarde geldt: de berekende som wordt nooit automatisch vervangen. Kiest u het documentcijfer, dan ziet u het als aangeleverd cijfer naast de berekende som, met het verschil; dat verschil wordt alleen getoond, niet verklaard.<br><br>Heeft u bij het uploaden een documentclassificatie opgegeven (groep, entiteit of algemeen, met overzicht, periode en cijfersoort) en blijkt die niet te kloppen, dan past u die achteraf aan met &lsquo;Classificatie wijzigen&rsquo; bij het document. Cijfers die eerder uit dat document zijn overgenomen, worden daarbij niet automatisch aangepast of gewist. Het document krijgt een markering, zodat u die cijfers zelf kunt controleren.')
    + stap(8,'Voortgang en samenvatting','Velden die u móet invullen zijn gemarkeerd met een rood "verplicht"-label naast het veldnaam. Het voortgangspercentage bovenin toont hoeveel verplichte velden per fase zijn ingevuld; via het samenvattingsscherm ziet u in één overzicht wat nog ontbreekt.')
    + stap(9,'Ondertekenen en vragen','Uw adviseur stuurt op het juiste moment de NDA, LoI of bemiddelingsovereenkomst ter digitale ondertekening (via Signhost). Via het Q&A-register kunt u ook zelf vragen van de koper beantwoorden zodra uw adviseur die aan u doorzet. Is de bemiddelingsovereenkomst met u als opdrachtgever verstuurd, dan verschijnt op uw eigen coverscherm een paneel waarin u de tekst leest en "Akkoord" of "Wijziging vragen" (met verplichte toelichting) kunt aangeven — pas ná uw akkoord kan uw adviseur de ondertekening (Signhost of buiten Signhost om) registreren; vraagt u een wijziging, dan maakt uw adviseur een nieuwe versie die u opnieuw beoordeelt.')
    + stap(10,'Meekijkers','Uw adviseur kan een externe partij die het traject heeft aangedragen of daar een gerechtvaardigd belang bij heeft (bijvoorbeeld een bank of accountant) beperkte, alleen-lezen inzage geven in een deel van uw dossier — dit gebeurt nooit zonder dat uw adviseur daar toestemming voor heeft. Onder "Wie kijkt er mee" op dit scherm ziet u altijd wie dat is (naam, type, welk onderdeel) en dat deze toegang op elk moment door uw adviseur kan worden ingetrokken.')
  );

  secties.koper = sectie('koper', '🤝 Koper', ''
    + stap('0a','Bent u opdrachtgever van een koopmandaat?','Heeft u Bisschops Financing ingeschakeld om een overname te zoeken, zónder dat er al een specifieke verkoper is? Dan logt u in met een aparte koopmandaat-code (dezelfde code-invoer als hieronder) en ziet u uw zoekprofiel en de kandidaat-ondernemingen die uw begeleider voor u volgt, inclusief hun status. Kandidaten zijn standaard anoniem: u ziet alleen een door uw begeleider goedgekeurde, geanonimiseerde omschrijving (bijvoorbeeld brede regio, sector, omzet- en medewerkersklasse). De bedrijfsnaam en sector ziet u pas nadat de onderneming akkoord heeft gegeven op een eigen introductieovereenkomst én uw begeleider de identiteit uitdrukkelijk aan u heeft vrijgegeven. Contactpersonen, de overeenkomst zelf en het akkoordbewijs ziet u nooit. Heeft uw begeleider een kandidaat aan u voorgesteld, dan geeft u op die kaart met "Ik heb interesse" of "Geen interesse" uw eigen keuze door; die keuze ziet u daarna terug. Uw keuze geeft de identiteit niet vrij: uw begeleider legt daarna eventueel een match vast en geeft de naam pas afzonderlijk vrij. Zodra een kandidaat serieus wordt en overgaat naar een echte transactie, ontvangt u daarvoor een eigen kopercode — vanaf dat moment gelden de NDA/dataroom/Q&amp;A-stappen hieronder gewoon. Is een aan u vrijgegeven kandidaat naar een traject gegaan, dan staat op die kaart "Open eigen traject": daarmee opent u dat traject met uw eigen kopertoegang. Is er (nog) geen vrijgegeven traject, dan ziet u een melding en gebeurt er niets.')
    + stap(1,'NDA eerst','Voordat u toegang krijgt, ontvangt en ondertekent u een geheimhoudingsovereenkomst (NDA). Zonder ondertekende NDA verleent de adviseur geen toegang.')
    + stap(2,'Inloggen','Na ondertekening logt u in op <code>mna.html</code> met uw persoonlijke <strong>koperscode</strong>.')
    + stap('2a','Uw route: de M&amp;A Journey','Op uw startscherm ziet u de veertien fasen van het traject. Zolang de geheimhoudingsovereenkomst niet geldig is getekend, ziet u alleen de route en uw eigen stap (de NDA), zonder bedrijfsgegevens. Na de NDA en de vrijgave ziet u uw eigen stappen, zoals een bod uitbrengen, de LoI en vragen stellen, met een knop die u direct naar de juiste plek brengt.')
    + stap(3,'Gefaseerde toegang','U ziet alleen de informatiecategorieën die de adviseur specifiek voor u heeft vrijgegeven — dit kan per fase verschillen en wordt gedurende het traject uitgebreid. Ziet u een categorie nog niet, dan is die simpelweg nog niet vrijgegeven.')
    + stap(4,'Dataroom en documenten inzien','Klik op "Alle documenten bekijken" op het startscherm voor een overzicht van alle vrijgegeven documenten (inclusief getekende NDA/BEM/Excl), met de automatisch geëxtraheerde kerncijfers per document. Documenten die door de verkoper alleen als bewijsstuk zijn toegevoegd (dus zonder AI-analyse) zijn herkenbaar aan het label "📎 Bewijsstuk" en hebben geen geëxtraheerde kerncijfers. Vanuit een informatiefase komt u via "Terug naar overzicht" weer bij dit startscherm.')
    + stap(5,'Vragen stellen (Q&amp;A)','Per informatiefase kunt u vragen stellen via het Q&amp;A-register. De adviseur (of verkoper, via de adviseur) beantwoordt deze en de antwoorden blijven in het dossier bewaard. Ná een antwoord kunt u doorpraten: elke vraag heeft een reactiedraad waarin u en de adviseur kunnen blijven reageren.')
    + stap(6,'Letter of Intent','Zodra de hoofdpunten zijn afgestemd, stelt de adviseur een LoI op ter ondertekening door beide partijen — dit ontgrendelt bij de verkoper ook de diepere fase-2-vragen.')
    + stap(7,'Meekijkers','Onder "Wie kijkt er mee" op dit scherm ziet u of er een externe partij (bijvoorbeeld een bank of accountant) beperkte, alleen-lezen inzage heeft gekregen in dit traject, en in welk onderdeel. Dit gebeurt alleen met toestemming van de adviseur en is op elk moment intrekbaar.')
    + stap('7b','Bemiddelingsovereenkomst (alleen als Bisschops Financing namens u bemiddelt)','Schakelt u zelf Bisschops Financing in bij deze aankoop, dan ontvangt u een bemiddelingsovereenkomst waarin u de opdrachtgever bent. Op uw coverscherm verschijnt dan een paneel om de tekst te lezen en "Akkoord" of "Wijziging vragen" (met toelichting) te geven — pas ná uw akkoord kan de ondertekening worden geregistreerd.')
    + stap(8,'Zelf een bod uitbrengen','Zodra u dossiertoegang heeft, kunt u op het startscherm zelf een indicatief bod indienen: vul een bedrag en desgewenst een toelichting in (voorwaarden, financieringsvoorbehoud, tijdlijn). Dit is nog niet bindend — de adviseur ontvangt uw bod en neemt daarna contact met u op. Deze optie staat alleen bij trajecten waar de adviseur de verkopende partij begeleidt.')
  );

  secties.begeleider = sectie('begeleider', '🧭 Begeleider (binnen een traject)', ''
    + stap(1,'Inloggen','U logt in op <code>mna.html</code> met uw <strong>tussenpersoonscode</strong> (uw eigen, unieke code per traject). Bij de eerste keer moet u de verwerkersovereenkomst (VOK) accepteren voordat het dashboard verschijnt.')
    + stap('1a','Werken in het traject: menu links en afzonderlijke schermen','Als begeleider werkt u in één scherm met links een vast menu: Dashboard, Journey, Due diligence, Documenten, Kandidaten (bij een verkoopmandaat), Communicatie, Analyse en waardering, Koper-toegang en onderaan de handleiding. Elk onderdeel opent als eigen scherm; u hoeft niet door één lange pagina te scrollen. Het dashboard is de startpagina: bovenaan staan de kerncijfers van het traject (omzet en EBITDA zoals ingevuld in de due diligence, het aantal ingevulde DD-velden, de huidige fase en het aantal kandidaten), daaronder de voortgang van de transactie in zes etappes, de volgende acties, de aandachtspunten (zoals nieuwe wijzigingen van de verkoper of afwijkingen tussen documenten) en snelkoppelingen naar alle onderdelen. Ontbreekt een gegeven, dan staat er dat het nog niet is ingevuld. De Journey toont alle 14 fasen, gegroepeerd in etappes; per fase ziet u de taken met uitvoerder en status, wie er aan zet is en de documenten van die fase. Opent u een document, analyse of gesprek, dan verschijnt het resultaat in het scherm waar u op de knop drukte. Op een tablet of telefoon staat het menu als balk bovenaan. Wilt u tijdelijk de vorige vormgeving gebruiken, open dan de pagina met ?ui=1 achter het adres; met ?ui=2 zet u de nieuwe vormgeving weer aan. Heb je het traject vanuit het adviseursportaal geopend met Open als begeleider, dan brengt de knop Adviseursportaal je terug naar het portaal waarin je al bent ingelogd.')
    + stap('1b','De M&amp;A Journey: veertien fasen met al uw documenten en taken','Op het dashboard staat de M&amp;A Journey, met veertien fasen: oriëntatie en intake, opdrachtverlening, voorbereiding (waardering, teaser en informatiememorandum), zoekprofiel en matching, longlist en selectie, teasercampagne, NDA en informatieverstrekking, shortlist en akkoord van de opdrachtgever, besprekingen en biedingen, LOI en exclusiviteit, due diligence, SPA en financiering, signing en closing, en nazorg. Bij een aankoop of fusie hebben de fasen een passende naam. Fasen die voor uw traject niet gelden, zoals het kandidatenproces bij een rechtstreeks gekoppelde koper, staan op niet van toepassing met de reden erbij. Meerdere fasen kunnen tegelijk lopen. De fasenbalk schuift opzij als niet alles in beeld past. Klik op een fase om de taken, de status per taak, wie de taak uitvoert, waar een taak op wacht en de bron van elke status te zien. De bekende documentkaarten (BEM, teaser, informatiememorandum, NDA, LoI, MoU, dealvoorstel, SPA, closing-checklist en de andere) staan nu in de fase waar ze horen en werken precies zoals voorheen. Kaarten zonder vaste fase staan onder Overige documenten. Rechtsboven ziet u de volgende stap. De statussen komen uit wat al in het dossier staat; u hoeft niets apart bij te houden. Bij een koopmandaat ziet u dezelfde veertien fasen op mandaatniveau, met per doelwit de uitkomst en de fase van de transactie zodra een doelwit een traject is geworden.')
    + stap('1e','Kandidaten: longlist, shortlist en het besluit van de opdrachtgever','Bij een verkoopmandaat opent u Kandidaten via het menu links. Zet kandidaten op de longlist met de knop Kandidaat toevoegen en geef per criterium (werkgebied, dienstverlening, omvang, software, cultuur, financiering) een score van 0 tot 100. Wat u niet weet laat u leeg: onbekend telt niet mee en wordt niet als nul gerekend. Naast de matchscore ziet u de dekking en hoe zeker de score is; klik op een naam voor de uitleg per criterium, het advies en de historie. Leg per kandidaat vast wat er gebeurt: teaser verstuurd, interesse, NDA getekend (met het getekende bestand uit het dossier als bewijs) en IM gedeeld. Het systeem staat alleen stappen in de juiste volgorde toe. Met de selectievakjes voert u een actie voor meerdere kandidaten tegelijk uit: eerst Controleren laat per kandidaat zien wat er gebeurt en waarom iets wordt overgeslagen, pas na Bevestigen wordt het uitgevoerd. Teasers, NDA-uitnodigingen en herinneringen verstuurt u vanuit het platform: kies de actie, controleer per kandidaat wat er gebeurt en bevestig dat u de ontvangers hebt gecontroleerd. Elke kandidaat krijgt een eigen e-mail met een persoonlijke, beveiligde link (geen bijlagen of vertrouwelijke inhoud). Via die link leest de kandidaat de anonieme teaser en meldt interesse, of geeft bij de NDA door wie ondertekent; de overeenkomst zelf stuurt u daarna via de bestaande ondertekenroute. Per kandidaat ziet u of de e-mail is verstuurd, geopend en beantwoord. Een verzending gaat nooit twee keer; mislukt er een, dan probeert u alleen die opnieuw. Wat u buiten het platform verstuurt, kunt u nog steeds zelf registreren. Contactgegevens vastleggen en kandidaten benaderen kan pas nadat u voor het traject de actuele verwerkersovereenkomst (versie 1.8) heeft geaccepteerd. U bent zelf verantwoordelijk voor deze benadering; de e-mail en de kandidaatpagina vermelden namens wie het bericht komt, waar de gegevens vandaan komen en verwijzen naar de privacyverklaring. Een kandidaat kan zich via de persoonlijke link afmelden met Niet meer benaderen: de contactgegevens worden dan verwijderd en de kandidaat krijgt geen berichten meer. Krijgt u zelf een bezwaar of verwijderverzoek, open dan de kandidaat en kies Kandidaat verwijderen; daarmee verdwijnen ook de historie en uitnodigingen. Onder Shortlist vergelijkt u de kandidaten per criterium en legt u de shortlist voor aan de opdrachtgever. Samenstellen is nog geen akkoord: de opdrachtgever besluit per kandidaat (akkoord of niet doorgaan), met datum. Pas na akkoord kunt u gesprekken, een bod en de LOI vastleggen.')
    + stap('1a','Koopmandaat — koper als opdrachtgever, vóór er een traject bestaat (25 sep 2026)','Heeft een koper u ingeschakeld om over te nemen, zónder dat er al een specifieke verkoper is? Dan ontvangt u van Bisschops Financing een aparte code voor een <strong>koopmandaat</strong> — hetzelfde inlogscherm, dezelfde code-invoer als bij een gewoon traject. Daarin legt u het zoekprofiel van de koper vast (sector, regio, omzetklasse) en voegt u kandidaat-ondernemingen ("targets") toe. Per target houdt u een status bij (kandidaat / in gesprek / geparkeerd / afgewezen), een contactlog en eigen werkaantekeningen — dit alles is alleen voor u; de koper ziet van elke target alleen de status en de door u goedgekeurde anonieme teaser, en pas na uw expliciete vrijgave ook naam en sector (zie stap 1c) — nooit uw notities of contactlog. Er is op dit niveau bewust nog geen dataroom, Q&amp;A of chat — dat ontstaat pas zodra u een target daadwerkelijk in due diligence neemt: met "Promoveer naar volwaardig traject" wordt de target een normaal transactietraject (met eigen verkoper-/koper-/tussenpersoonscode), waarbij naam, sector en uw notities automatisch overgenomen worden. Die knop opent het adviseursportaal in een nieuw tabblad: u logt daar in met het account dat eigenaar is van het koopmandaat (wachtwoord, verificatiecode en zo nodig de gebruiksvoorwaarden), ziet de actuele pakketprijzen zoals de server die opgeeft (inclusief een eventuele testboeking of vrijstelling), kiest zelf uitdrukkelijk een pakket en de sector — bij een ontbrekende of onbekende sector wordt niets aangenomen — en bevestigt pas daarna. Weigert de server (bijvoorbeeld een ander account, trajectlimiet, proefperiode of een niet ingesteld tarief), dan ziet u die melding en is er niets gestart; u kunt het opnieuw proberen. Na bevestiging gaat u met "Verder als begeleider" naar het nieuwe traject. "Open het traject" bij een al gepromoveerde target gaat eveneens via het adviseursportaal en opent het traject alleen als het in de trajectenlijst van uw account staat. Andere targets in hetzelfde koopmandaat blijven gewoon staan; u kunt er later nog meer promoveren of eraan toevoegen. Een verkoper hoeft dus niet vanaf dag één bekend te zijn — u kunt maanden in de zoek-/screeningsfase zitten voordat een target een echt traject wordt.')
    + stap('1c','Introductieovereenkomst met de target en vrijgave van de identiteit (N-115, 3 okt 2026)','Per target opent u in het koopmandaat "Introductieovereenkomst &amp; vrijgave". <strong>(1) Overeenkomst</strong> — u voert de tekst zelf in en stelt een versie vast. Dit is een eigen overeenkomst met de target, geen bemiddelingsovereenkomst; het platform levert geen standaardtekst. De goedgekeurde richting (partijen, doel en geselecteerde koper, geen fee voor de target, transparantie over uw betaalde koperopdracht, vertrouwelijkheid, begrensde introductiebescherming, geen transactieplicht, nieuw akkoord bij een nieuwe versie, afzonderlijke vrijgave, einde en bewaring) moet nog juridisch worden gevalideerd; neem geen boete- of duurbepalingen op waarover niet is besloten. Een nieuwe inhoudelijke versie vraagt uw bevestiging: de huidige link, een eventueel akkoord en een eventuele vrijgave vervallen dan. <strong>(2) Link</strong> — u maakt een persoonlijke link (1 tot 30 dagen geldig, standaard 14) en kopieert die of opent er een e-mail mee in uw eigen mailprogramma; er wordt niets automatisch verstuurd. De link is alleen direct na aanmaken zichtbaar; een nieuwe link of "Link intrekken" maakt de vorige ongeldig, en u ziet steeds of de link actief, verlopen of ingetrokken is. Contactnaam en e-mailadres mag u leeg laten. <strong>(3) Reactie van de target</strong> — de target leest de overeenkomst, bevestigt bevoegd te zijn en geeft akkoord, of vraagt een wijziging; beide ziet u terug met versienummer, naam en tijdstip. <strong>(4) Teaser</strong> — u stelt een anonieme teaser samen (brede regio, gestandaardiseerde sector, omzet- en medewerkersklasse, korte omschrijving) en keurt die bewust goed na controle op herleidbaarheid; er wordt niets automatisch overgenomen uit naam, sector, notities of bron. Optioneel (begeleider of beheerder, niet bij een gearchiveerde of gepromoveerde target) kiest u "AI-teaservoorstel opvragen (optioneel)": alleen de gekozen vaste keuzes (brede regio, sector uit de standaardlijst, omzet- en medewerkersklasse) gaan naar AI — geen naam, omschrijving, notities, contactgegevens of codes. Een eigen, niet-standaard sector wordt daarbij afgewezen; laat de sector dan weg of schrijf de omschrijving zelf. Een geldig voorstel komt alleen in het omschrijvingsveld en is onbevestigd: niet opgeslagen, niet goedgekeurd, niet voorgesteld aan de koper en niet vrijgegeven. Staat er al tekst in de omschrijving, dan vraagt het platform eerst of u die wilt vervangen; wijzigt u omschrijving, keuzes of vinkje terwijl het voorstel wordt opgehaald, of sluit u het venster, dan wordt het voorstel niet overgenomen. Het ophalen wacht maximaal drie minuten en wordt niet automatisch herhaald. Na een voorstel zet u de anonimiteitscontrole opnieuw zelf aan en kiest u zelf "Teaser goedkeuren". Bij een afwijzing of fout blijven uw tekst en keuzes staan; de handmatige teaser blijft altijd beschikbaar. <strong>(5) Vrijgave</strong> — een akkoord geeft de identiteit niet vrij. Pas als u na akkoord op de actuele versie op "Identiteit vrijgeven aan de koper" klikt, ziet de koper naam en sector; alleen de begeleider kan dit, niet de platformbeheerder. <strong>(6) Einde en bewaring</strong> — met een reden legt u het einde van de introductierelatie vast (start van de bewaartermijn van vijf jaar voor overeenkomst en akkoordbewijs), het einde van de operationele noodzaak van de contactgegevens (daarna uiterlijk zes maanden), of een gerichte langere bewaring van alleen het noodzakelijke bewijs bij een geschil of juridische noodzaak. Dit bewaarbeleid is productbeleid en wordt nog juridisch en op privacy gevalideerd. Na promotie blijft de overeenkomst bij de oorspronkelijke target; in het traject opent u hem alleen-lezen via "Introductieovereenkomst" in de trajectkop. De koper ziet de overeenkomst en het bewijs nooit.')
    + stap('1d','Potentiële targets — generieke targetflow tot match en promotie (4 okt 2026)','In het koopmandaat staan uw targets onder <strong>Potentiële targets</strong>. Elke target volgt zijn eigen stappen; een actie op de ene target verandert niets aan een andere. <strong>(1) Nieuwe target</strong> — "+ Target toevoegen" maakt altijd een target in de generieke targetflow, met startstatus nieuw, benaderd of in gesprek. U legt bedrijfsnaam, een <em>interne</em> anonieme naam (nooit zichtbaar voor de koper en nooit automatisch gedeeld), sector, bron, KvK-nummer, rechtsvorm, bedrijfsadres, contactpersoon met e-mail en telefoon, en datum en kanaal van de eerste benadering vast. Met "Gegevens bewerken" past u dit later aan; alleen gewijzigde velden worden opgeslagen. De contactpersoon is dezelfde als in het venster van de bevestiging (één bron, geen dubbele invoer). Een telefoonnummer wordt alleen vastgelegd naast een contactnaam of e-mailadres. Bestaande targets houden hun flow; met "Overzetten naar de generieke targetflow" (eenmalig, met bevestiging) gelden daarna ook voor hen de stappen hieronder. <strong>(2) Voortgang</strong> — op elke kaart ziet u welke stappen klaar zijn en wat de volgende stap is. Vastgesteld, link, akkoord en teaser leest het platform af uit de echte versie, link, het akkoord en de teaser; het zijn geen losse statussen. Handmatig kiest u alleen nieuw, benaderd, in gesprek, geparkeerd of afgewezen. <strong>(3) Bemiddelings-/introductiebevestiging</strong> — in "Bemiddelings-/introductiebevestiging, teaser &amp; vrijgave" laadt u met "Concept BEMIDDELINGS-/INTRODUCTIEBEVESTIGING laden" een concept uit een vast sjabloon (niet door AI opgesteld, er wordt niets opgeslagen). Optioneel kiest u "AI-voorstel opvragen (optioneel)": u krijgt een taalkundige variant van hetzelfde sjabloon; uw tekst en partijgegevens gaan niet naar AI. Dat AI-voorstel is onbevestigd: niet opgeslagen, niet vastgesteld, niet verstuurd, niet vrijgegeven en niet juridisch goedgekeurd. Staat er al eigen tekst in het tekstvak, dan vraagt het platform eerst of u die wilt vervangen; wijzigt u de tekst terwijl het voorstel wordt opgehaald, dan blijft uw tekst staan. Lukt het AI-voorstel niet (bijvoorbeeld geen verbinding, te veel verzoeken of AI niet beschikbaar), dan blijft het vaste sjabloon gewoon beschikbaar. Ontbrekende gegevens staan als [in te vullen: …] in de tekst en in een lijst. U past de tekst aan en stelt hem vast als versie; open punten vragen een extra bevestiging. Ook een AI-voorstel wordt pas een versie als u het zelf vaststelt; er volgt geen automatische link, e-mail, akkoord of vrijgave, en juridische eindvalidatie gebeurt altijd afzonderlijk. Dit is geen verkoopopdracht en geen bemiddelingsovereenkomst; de BEM en eerder vastgestelde teksten veranderen niet. <strong>(4) Versturen</strong> — u maakt een persoonlijke link en opent met "E-mail openen in uw mailprogramma" een e-mail in uw eigen mailprogramma; het platform verstuurt niets. "Link aangemaakt" betekent alleen dat de link bestaat. Pas als u op "Ik heb de e-mail verstuurd — verzending vastleggen" klikt, staat er een contactmoment en toont de voortgang "verzonden (door u vastgelegd)"; het platform heeft geen bezorgbevestiging. De onderneming geeft akkoord of vraagt een wijziging; u ziet versie, status en tijdstip, ook na het opnieuw openen. <strong>(5) Voorstellen, interesse en match</strong> — na een goedgekeurde anonieme teaser kiest u "Voorstellen aan de koper": de koper ziet alleen die teaser. De koper geeft zelf "Ik heb interesse" of "Geen interesse" aan; geeft de koper zijn keuze aan u door, dan legt u die vast. Bij interesse kiest u "Match vastleggen" (met bevestiging); "Match intrekken" vraagt een reden. Interesse, akkoord en match geven de identiteit nooit vrij; dat blijft de afzonderlijke vrijgave (stap 1c). <strong>(6) Promotie</strong> — bij een target in de generieke flow verschijnt "Promoveer naar volwaardig traject" pas na match én vrijgave; anders ziet u wat nog ontbreekt. De promotie zelf gaat zoals beschreven bij stap 1a (adviseurslogin, kostenbevestiging) en neemt naam, sector, notities, contactpersoon, rechtsvorm, adres en KvK-nummer over. Target, bevestiging, akkoord, vrijgave, teaser, contactlog en historie blijven bewaard. <strong>(7) Archiveren</strong> — "Archiveren" (met reden) verwijdert niets: versies, akkoorden, vrijgave, teaser, contactlog en historie blijven bewaard volgens het bestaande bewaarbeleid. Een actieve persoonlijke link wordt ingetrokken en de koper ziet de target niet meer. Gearchiveerde targets staan onderaan; met "Herstellen" (met reden) gaat u verder waar u was. <strong>(8) Historie</strong> — per target ziet u wie wat wanneer deed (veldnamen, statussen, interessekeuzes, redenen; geen contactgegevens). De bevestigingstekst en het bewaarbeleid zijn nog juridisch te valideren.')
    + stap('1b','Cliëntacceptatie — beslisboom','Op het dashboard bevestigt u met het vinkje "Cliëntacceptatie getoetst" dat u de betrokken partijen heeft gecontroleerd. Praktische volgorde om dat te doen: <strong>(1) Identiteit</strong> — KvK-uittreksel en ID van de tekenbevoegde(n) kloppend en niet verlopen? Twijfel hierover: eerst ophelderen, nog niet verder. <strong>(2) UBO\'s</strong> — de uiteindelijk belanghebbenden in kaart en gecontroleerd tegen het UBO-register? <strong>(3) Sanctielijsten</strong> — alle betrokken partijen en UBO\'s gecontroleerd op EU-/OFAC-sanctielijsten? Bij een treffer: traject niet starten, contact opnemen met Bisschops Financing. <strong>(4) PEP</strong> (politiek prominente personen) — bij een treffer: verhoogd risico, vraag expliciet door naar de herkomst van middelen vóórdat u verdergaat. <strong>(5) Doel van de relatie</strong> — is helder en logisch waarom deze partij dit traject aangaat? Vaag of onduidelijk: eerst doorvragen. <strong>(6) Herkomst van middelen</strong> (bij een koper: de financieringsbron) — aannemelijk en zo nodig onderbouwd met bewijsstukken? Pas als u op alle zes punten een bevredigend antwoord heeft, vinkt u "Cliëntacceptatie getoetst" aan en legt u dat kort vast in het notitieveld ernaast. Dit is praktische richtlijnbepaling, geen juridisch advies — uw eigen Wwft-verplichtingen (indien van toepassing op uw praktijk) blijven onverkort uw eigen verantwoordelijkheid.')
    + stap(2,'Dashboardoverzicht','Bovenaan de Documenten-flow ziet u een groene badge "Volgende stap" bij het eerstvolgende document dat logisch aan de beurt is (bemiddelingsovereenkomst, teaser, dan geheimhouding) — die badge verschijnt alleen voor dit vroege, strikt volgtijdelijke deel van een traject; daarna staat het u vrij in welke volgorde u verdergaat. U ziet de voortgang per fase, de dataroom, het Q&amp;A-register, en — indien de module "Contracten" actief is — knoppen om documenten te genereren: NDA, LoI, BEM (bemiddelingsovereenkomst), Excl (exclusiviteitsovereenkomst), Dealvoorstel, Bieding, SPA en Closing-checklist (een algemene controlelijst ter voorbereiding op closing — juridische documentatie, financiële afwikkeling, corporate handelingen, fiscale afwikkeling, personeelsaandachtspunten en post-closing-aandachtspunten, geen juridisch advies). Is de module niet actief, dan zijn de knoppen zichtbaar maar vergrendeld. Bij het versturen van een LoI of een indicatieve bieding is een extra veld "Intern goedgekeurd door" verplicht — pas als dat is ingevuld én het akkoord-vinkje is aangevinkt, wordt de verzendknop actief. Bij een <strong>fusietraject</strong> vraagt deze stap twee namen (één per fusiepartij), omdat een fusie gezamenlijke goedkeuring vanuit beide besturen vereist; beide zijn verplicht en beide worden gelogd. Dit wordt vastgelegd in het logboek (wie, wanneer, welk document, welk verzendkanaal) — een bewuste, lichte controlestap vóór het versturen van deze twee dealkritieke documenten. De BEM-knop kiest automatisch de juiste onderliggende tekst op basis van het trajecttype: verkoop en aankoop hebben elk hun eigen succesfee-staffel (5%/4%/3%/2% over de transactiewaarde, minimaal €25.000), en bij trajecttype "Opvolging" wordt een apart bedrijfsopvolgings-sjabloon gebruikt (met een extra artikel voor het geval de opvolger al bekend is, bijv. een partner of familielid) — u hoeft zelf niets te kiezen. Zodra u de bemiddelingsovereenkomst per e-mail verstuurt, krijgt de opdrachtgever (bij verkoop de verkoper, bij aankoop de koper — automatisch bepaald) op zijn eigen coverscherm dezelfde reviewcyclus als bij MoU/LoI/NDA: "Akkoord" of "Wijziging vragen" (met toelichting), zichtbaar in de reactiestatus onder het document in uw eigen dashboard. Vraagt de opdrachtgever een wijziging, dan blijft de verstuurde versie ongewijzigd bewaard; u verstuurt een aangepaste tekst opnieuw, wat automatisch een nieuwe, opnieuw te beoordelen versie start. Zowel Signhost als "Buiten Signhost om getekend" zijn pas beschikbaar nadat de opdrachtgever inhoudelijk akkoord heeft gegeven. Onder elk gegenereerd document staat een vaste slotregel dat het via het platform is opgesteld als hulpmiddel en geen professioneel advies of taxatierapport is. Bij <strong>versturen</strong> (e-mail/Signhost) wordt die regel automatisch aan het document aangehecht. Bij <strong>printen/bekijken</strong> vraagt het platform u deze eerst te bevestigen in een pop-up — die bevestiging wordt vastgelegd, maar de regel zelf komt niet in het printvenster te staan, zodat u ook een schone versie kunt printen.')
    + stap('2h','Terugweg naar het portaal in elke document-e-mail (22 sep 2026)','Elke e-mail met een MoU, LoI, NDA, BEM, Exclusiviteitsovereenkomst, Dealvoorstel of Indicatieve bieding bevat nu een link terug naar het portaal, die de ontvanger automatisch inlogt met zijn eigen code — voorheen kreeg de ontvanger bij MoU/LoI/NDA alleen "zie de bijlage" te lezen, zonder enige weg terug naar de al bestaande beoordelingsfunctie.')
    + stap('2i','Exclusiviteitsovereenkomst — dezelfde reviewcyclus, maar bindt beide partijen','De Exclusiviteitsovereenkomst krijgt dezelfde "Akkoord"/"Wijziging vragen"-cyclus als BEM, met één inhoudelijk verschil: omdat exclusiviteit verplichtingen schept voor zowel de verlenende (verkoper) als de ontvangende partij (koper), telt het document pas als "goedgekeurd" zodra <strong>beide</strong> partijen akkoord hebben gegeven — één akkoord is niet genoeg, en een wijzigingsverzoek van één partij weegt altijd zwaarder dan het akkoord van de ander. Signhost en "Buiten Signhost om getekend" zijn pas beschikbaar ná dat gezamenlijke akkoord. U verstuurt de brief zoals gebruikelijk; beide partijen ontvangen ieder hun eigen, gepersonaliseerde e-mail met portaallink.')
    + stap('2j','Dealvoorstel en Indicatieve bieding — terugvindbaar, geen formeel akkoord','Deze twee documenten gaan naar de verkoper (Dealvoorstel) resp. beide partijen (Indicatieve bieding), maar zijn onderhandelingsdocumenten, geen overeenkomst — er is dus geen Akkoord/Wijziging-knop. Wel is het document nu terug te vinden in het portaal (voorheen alleen een PDF in de mail, daarna spoorloos) en kan de ontvanger het bespreken via het bestaande Q&amp;A-register.')
    + stap('2k','Teaser en Verkoopmemorandum daadwerkelijk versturen (22 sep 2026)','Beide konden al gegenereerd, bewerkt, opgeslagen en geprint worden, maar niet vanuit het platform verstuurd — u moest ze zelf kopiëren of los mailen. Bij "Teaser bekijken/bewerken" en "Verkoopmemorandum bekijken/bewerken" staat nu onderaan een veld voor het e-mailadres van de ontvanger (een zelf gekozen geïnteresseerde partij, geen vaste verkoper-/kopercode) plus een Verstuur-knop. Dit zijn informatieve documenten — er is bewust geen reviewcyclus (geen Akkoord/Wijziging-vragen) aan gekoppeld, alleen een audit-spoor van wanneer en naar wie is verstuurd.')
    + stap('2d','Memorandum of Understanding (MoU-composer)','De MoU-composer (in de Documenten-flow, tussen NDA en LoI) stelt een intentiedocument samen uit losse onderdelen: partijen, reikwijdte en structuur van de transactie, indicatieve koopprijs, prijsmechanisme en betaalstructuur, due diligence, financiering, opschortende voorwaarden, tijdpad, geheimhouding, exclusiviteit, kostenverdeling, rechtskeuze en forum, plus de vaste onderdelen "bindende bepalingen", "niet-bindendheid" en de reliance-voettekst. Elk onderdeel is een leeg werkveld met eigen invulvelden en een vrij tekstvak. Een deel van de gegevens is al voorgevuld uit het traject; per onderdeel kunt u een AI-<em>concept</em>tekst laten voorstellen. Bij elk veld staat de herkomst (ingevoerd, uit een bron, berekend, aanname, AI-concept, door een specialist afgetekend, platform). Onderdelen voegt u toe of haalt u weg via "Onderdelen samenstellen"; de composer toont welke KERN-onderdelen nog ontbreken. Per vakgebied (juridisch, fiscaal, cijfers) markeert u een onderdeel als beoordeeld, met de naam en hoedanigheid van wie aftekende; wijzigt u daarna nog iets aan dat onderdeel, dan vervalt die aftekening automatisch en is een nieuwe beoordeling nodig. De aftekeneis per vakgebied kunt u uitzetten — dat wordt gelogd en op het document vermeld. Wijkt een gekoppeld veld af van de dealgegevens of van een ander document in hetzelfde traject, dan verschijnt bovenaan een afwijkingsmelding; het platform bepaalt niet welke waarde juist is. Met "Finaliseer &amp; exporteer" zet u het document vast: dat kan alleen als alle KERN-onderdelen zijn opgenomen, alle vereiste aftekeningen er zijn en de verplichte velden zijn ingevuld — anders krijgt u een lijst met wat er nog moet gebeuren. Bij finaliseren wordt een compact manifest vastgelegd (welke onderdelen in welke versie, welke beoordelingen met hoedanigheid, welke reliance-versie, hashes van de tekst) zodat later aantoonbaar is waaruit die documentversie bestond, ook nadat de trajectinhoud is verwijderd. Daarna is het document vergrendeld; u verstuurt het naar verkoper en/of koper met de vaste voettekst eronder, en kunt het manifest bekijken. Bovenin de composer staat ook een knop "Print / PDF" — die drukt de onderdelen af zoals ze op dat moment op het scherm staan (titel + tekst per onderdeel), zowel als concept tijdens het samenstellen als na finaliseren. De professionele tekst per onderdeel blijft het werk van uw eigen jurist, fiscalist of waarderingsdeskundige, afgestemd op dit dossier; de AI levert hoogstens een concept ter beoordeling. Dezelfde composer staat ook, als eigen knop verderop in dezelfde flow, voor twee andere documenttypen: de <strong>Letter of Intent (LoI)</strong> — uitgebreider dan de MoU, met standaard ook een kader voor garanties/vrijwaringen en een MAC-clausule (wezenlijk nadelige wijziging) erin, en standaard zowel juridische als fiscale beoordeling vereist — en de <strong>Geheimhoudingsovereenkomst (NDA)</strong> — korter en grotendeels bindend, alleen juridische beoordeling vereist, met eigen onderdelen voor doel/vertrouwelijke informatie, toegestane ontvangers, duur &amp; teruggave en een boetebeding. <strong>Sinds 11 september 2026 is de composer de enige weg om een NDA of LoI aan te maken</strong> — de oudere sjabloongenerator voor deze twee documenttypen is uit de flow gehaald (achter de schermen blijven eerder aangemaakte sjabloondocumenten gewoon bewaard en zichtbaar). Zodra u een MoU, LoI of NDA heeft gefinaliseerd &amp; verstuurd, verschijnt bij de verkoper en/of koper (afhankelijk van de gekozen adressaten) automatisch een paneel op hun eigen coverscherm met daarin twee losse stappen (partij-reviewcyclus, 20 september 2026). <strong>Stap 1 — inhoudelijke reactie:</strong> de partij leest de tekst en klikt op "Akkoord" of "Wijziging vragen" (met verplichte toelichting). Bij meerdere geadresseerden telt elke partij apart mee: pas als alle geadresseerde partijen akkoord hebben gegeven, telt het document als "goedgekeurd"; vraagt één partij een wijziging, dan telt dat altijd zwaarder dan een akkoord van de ander. U ziet in het dossier per partij of, hoe en wanneer gereageerd is, inclusief de toelichting bij een gevraagde wijziging. Reageert een partij "wijziging gevraagd", dan blijft de verstuurde versie ongewijzigd bewaard (niets wordt overschreven); u maakt via "Nieuw document" een volgende versie aan, die weer een eigen, schone reviewronde start — een eerder verstuurde, inmiddels vervangen versie kan daarna niet meer beoordeeld worden. <strong>Stap 2 — ondertekenen (alleen LoI/NDA, geen MoU):</strong> verschijnt pas ná de eigen inhoudelijke reactie uit stap 1 (akkoord óf wijziging gevraagd) — ongewijzigd de bestaande "Akkoord &amp; onderteken"-knop, die dezelfde vlag zet die fase 2 (verkoper) resp. de identiteitsvrijgave (koper, ná NDA) ontgrendelt.')
    + stap('2e','Review uit de specialistenpool','Heeft u voor een vakgebied (juridisch, fiscaal of cijfers) geen eigen jurist / fiscalist / waarderingsspecialist, dan kunt u er één inschakelen uit de door Bisschops Financing samengestelde pool. In het composer-blok "Beoordeling &amp; aftekening" staat "Vraag een review aan uit de pool": u kiest eerst het vakgebied, waarna de specialistenlijst zich hergroepeert — specialisten die bij dat vakgebied passen staan bovenaan (u ziet alleen het profiel, tarief en indicatieve doorlooptijd — nooit trajecten van anderen), geeft een korte instructie en een deadline, en ziet de <strong>kosteninschatting vóór bevestigen</strong> (honorarium van de specialist + platformbemiddeling). Na bevestigen krijgt u een link die u zelf naar de specialist stuurt. De specialist opent die link, ziet uitsluitend de gescopte onderdelen van dit ene document (alleen de ingevulde waarden en de concepttekst — geen andere trajecten, geen toegangscodes), en tekent af met zijn naam en hoedanigheid. Daarmee gaan de onderdelen van dat vakgebied op "afgetekend" en opent de finaliseer-poort. De aftekening is de professionele verantwoordelijkheid van die specialist. Het is een optie, geen verplichting: wilt u de pool niet gebruiken, dan zet u de aftekeneis voor dat vakgebied uit (dat wordt gelogd en op het document vermeld) of tekent u zelf af als eigen controle.')
    + stap('2f','Uw eigen specialist inzetten (in plaats van de pool)','Heeft u zelf al een vaste jurist, fiscalist of waarderingsdeskundige? Dan hoeft u niet de pool te gebruiken. U voegt uw eigen specialist toe — bij het aanmaken van een nieuw traject (optioneel veld "Eigen specialist"), of later vanuit hetzelfde composer-blok via "+ Eigen specialist toevoegen" (naam, hoedanigheid, kantoor, e-mailadres, eventueel een inschrijvingsnummer). Aan het toevoegen is een eenmalige vergoeding verbonden; die verschijnt na het toevoegen. Uw eigen specialist verschijnt daarna als aparte optie in de specialistenlijst bij "Review aanvragen", herkenbaar aan de groep "Uw eigen specialisten". De rest van de flow is identiek aan de pool: u krijgt een link voor de specialist, die de gescopte onderdelen inziet en aftekent — alleen zonder een aparte platformbemiddelingskosten per review, want die zijn al met de toevoegvergoeding afgedekt. <strong>Belangrijk:</strong> wie u op deze manier inzet, is en blijft uw eigen zaak — Bisschops Financing krijgt de naam, het kantoor of het e-mailadres van uw eigen specialist nooit te zien, in geen enkel overzicht.')
    + stap('2g','Koopovereenkomst (SPA) — AI-concept','De knop "Koopovereenkomst (SPA)" in de Documenten-flow genereert sinds 11 september 2026 een volledig AI-concept van de koopovereenkomst (16 artikelen: definities, koop en levering, koopprijs, opschortende voorwaarden, closing, garanties, aansprakelijkheid, non-concurrentie, etc.) — niet langer alleen een aandachtspuntenlijst. De koopsom in Artikel 3 wordt automatisch overgenomen uit het laatst verstuurde dealvoorstel. De juridisch meest onderhandelde onderdelen (drempels, plafonds, termijnen in de aansprakelijkheidsclausule, notarisnaam, non-concurrentiegebied e.d.) blijven bewust als [placeholder] staan — de AI verzint daar nooit een bedrag of termijn bij. <strong>Dit blijft een concept, geen getoetste overeenkomst:</strong> laat uw eigen jurist de tekst, met name de garantie- en aansprakelijkheidsartikelen, beoordelen en definitief vaststellen vóór ondertekening. Heeft u liever uw eigen tekst (van uw jurist, of een vast kantoorsjabloon)? Plak die gewoon over de gegenereerde tekst heen, of gebruik "Eigen document versturen" verderop in de flow. Vóór u de tekst in gebruik neemt, vult u uw naam in bij "Intern goedgekeurd door" en klikt u op "Vastleggen — ik gebruik deze tekst": dat legt vast, met naam en tijdstip, dat dit uw eigen, verantwoordelijke keuze was om deze tekst (AI-concept of eigen tekst) te gebruiken. De SPA gaat, anders dan NDA/LoI/BEM/Excl, nooit via het platform naar verkoper of koper — geen verstuur- of Signhost-knop; u deelt de definitieve versie zelf, buiten het platform om, zodra uw jurist die heeft vastgesteld.')
    + stap('2h','Fase Financieel — alleen door de verkoper','De DD-fase "Financieel" (cijfers, checklist en notities) toont u read-only — alleen de verkoper zelf mag deze invullen of wijzigen (12 sep 2026: de verkoper is en blijft verantwoordelijk voor de eigen financiële opgave). Ziet u een onjuistheid of iets dat aandacht verdient? Meld dat via de chat met de verkoper of via een informatieverzoek — de verkoper verwerkt het dan zelf. Documenten voor deze fase (incl. bankmutaties) uploadt u ook niet zelf; verwijderen of aan een andere fase koppelen van een reeds geüpload document kan wel, net als bij elke andere fase. Zodra er bankmutaties zijn geüpload, verschijnt er ook een cashflow-overzicht (instroom/uitstroom per maand, met een keuze voor 3/6/12 maanden) — dat overzicht is zichtbaar voor u, de verkoper, en de koper (zodra financieel is vrijgegeven). Bij de 12-maandenweergave verschijnt automatisch een melding als een of meer maanden geen enkele mutatie bevatten — een signaal dat mogelijk een bankafschrift ontbreekt, geen definitief oordeel. Daarnaast kunt u zelf een red-flag-analyse laten genereren op de bankmutaties (alleen zichtbaar voor u, nooit automatisch voor verkoper/koper) — vóór ondertekening van de LoI heet dit "Financiële Quick Scan" (een vroege, lichtere analyse ter ondersteuning van waardering/bieding/LoI-voorwaarden, nadrukkelijk geen volledige due diligence), ná de LoI heet exact dezelfde analyse "Volledige Bank-DD" (dezelfde onderliggende bevindingen, dus geen dubbel werk of gegevensverlies bij de overgang). Deze signalen passen nooit automatisch de waardering of prijs aan, en elke bevinding krijgt een eigen status (open/vraag uitstaand/beantwoord/gesloten/vervallen) die u zelf bijwerkt en die blijft staan, ook als u de analyse later opnieuw laat draaien. Met "Maak hier een vraag van" zet u een bevinding in één klik om in een gewone Q&A-vraag voor deze fase, zodat u die op de normale manier kunt opvolgen. Met "Classificeer transacties" labelt u de bankmutaties zelf (omzet/leverancier/personeel/belasting/lening/privé-gelieerd/overig zakelijk/onbekend) — zichtbaar in de transactietabel voor u, de verkoper en de koper. Bankafschriften leest de verkoper zelf in, ook als ze al met de andere documenten in het dossier staan; dubbele transacties uit hetzelfde afschrift in een ander formaat worden daarbij herkend en niet dubbel geteld.')
    + stap(3,'AI-analyse &amp; waardering','Twee waarderingsfeatures naast elkaar: (1) de deterministieke rekenkern voor closing/earn-up/buy-and-build-scenario\'s, inclusief IRR en Multiple-on-Money bij buy-and-build; (2) een onafhankelijke AI-"second opinion" die zelf een multiple/bandbreedte bepaalt op basis van sectorbenchmarks, met bronvermelding en een automatische sanity-check. Op het waarderingsscherm staat naast de PDF-knop ook een CSV-knop — downloadt de financiële basis, kengetallen/ratio\'s, waardebepaling, rolling forecast en earn-out-structuur als één bestand dat direct in Excel opent. De waardebepaling en de earn-out-structuur staan er ook als grafiek bij: een staafdiagram voor de laag/midden/hoog-bandbreedte en een waterfall-grafiek die laat zien hoe de koopsom bij closing plus de jaarlijkse earn-out-uitkeringen optellen tot het totaal. Onder de waardebepaling staat een <strong>Management- &amp; sleutelpersoonrisico</strong>-blok: een kwalitatieve laag/midden/hoog-indicatie, afgeleid uit de ingevulde velden (tweede echelon, key-person-afhankelijkheid, veranderbereidheid, retentieafspraken, opvolging). Het is een aandachtspunt voor het retentiepakket en de risicoparagraaf — <strong>nooit een automatische correctie op de multiple of de waardering</strong>; bij te veel onbekende velden vervalt het oordeel ("onvoldoende ingevuld"). Hetzelfde blok verschijnt in het gegenereerde Dealvoorstel. Onder een AI-waardering staat de knop <strong>Goedkeuren als indicatieve waardering</strong>. Alleen de laatst goedgekeurde waardering verschijnt op het dashboard, als indicatief bedrag met bandbreedte, methode en peildatum. Goedkeuren maakt geen document aan. Zijn de financiële gegevens daarna gewijzigd, dan staat erbij sinds wanneer de waardering verouderd is; een nieuwe waardering maakt u zelf.')
    + stap(4,'Waarderingsmodellen in het Dealvoorstel — wat elke methode precies berekent','Naast de hoofdwaardering (EBITDA-multiple, of een omzet-multiple bij sectoren zoals zorg waar dat gebruikelijker is — het scherm toont altijd welke grondslag geldt) toont het Dealvoorstel altijd een <strong>opbrengst-brug</strong> ("Van ondernemingswaarde naar opbrengst bij closing"): de headline-ondernemingswaarde is niet wat de verkopende partij als geld ontvangt — netto schuld van het doelwit, debt-like items, een werkkapitaalcorrectie en transactiekosten gaan eraf tot de equity value, en escrow plus een eventuele uitgestelde earn-out worden pas later uitgekeerd. Het eindbedrag "cash bij closing" en de "verwachte gerealiseerde waarde" (het optimistische scenario: escrow volledig vrijgegeven, earn-out volledig behaald) staan er als tabel én waterfall-grafiek bij. De aftrekposten zijn <strong>door u ingevoerde aannames</strong> — de netto schuld is voorgevuld uit de balansvelden als die zijn ingevuld, de rest vult u zelf in; het platform verzint hier geen bedrag. Direct onder de opbrengst-brug staat de <strong>onderhandelruimte</strong> ("Onderhandelruimte: verdeling van de opbrengst naar zekerheid"): de waardepositie van de verkoper ingedeeld naar zekerheid en timing — zeker bij closing (contant), escrow (uitgesteld maar doorgaans zeker), voorwaardelijk (earn-out, de voorwaardelijke earn-up en een eventuele verkoperslening) en behouden belang (geen betaling van de koper — de waarde van het niet-verkochte deel, pas vast bij een tweede exit). Als tabel én gestapelde balk. Dit bouwt op de opbrengst-brug plus de earn-up (die daarbij van EV-toerekening naar de equity/cash-basis van de verkoper wordt herrekend); zolang er een earn-up bestaat is de voorwaardelijke laag dus nooit 0. Het laat zien waar in de onderhandeling ruimte zit — bijvoorbeeld een groter deel cash bij closing tegen een lagere prijs, een kortere escrow, een kleinere earn-out-tranche of meer/minder behouden belang. Alleen bij een verkoop- of opvolgingstraject vult u in het formulier ook een <strong>BATNA &amp; walk-away</strong> in (in overleg met de verkoper): de <strong>walk-awayprijs</strong> is de minimale opbrengst waaronder het alternatief zonder deze deal aantrekkelijker is; daarnaast kiest u het alternatief zelf (zelfstandig doorgaan, later verkopen, andere koper, minderheidsinvesteerder, overdracht familie/management, afbouwen), een optionele geschatte waarde daarvan, en de tijdsdruk van de verkoper. Het voorstel toetst de dealopbrengst dan tegen die ondergrens en geeft een oordeel <strong>BOVEN</strong> (zelfs de zekere cash bij closing ligt erboven), <strong>KRAP</strong> (alleen mét volledige escrow/earn-out) of <strong>ONDER</strong> (ook in het beste geval eronder — niet accepteren zoals het nu ligt). Laat u de walk-awayprijs leeg, dan velt het voorstel géén oordeel — er wordt geen ondergrens verzonnen. Dit blok is uitsluitend voor de verkoper en u; het hoort niet in wat naar de koper gaat. Bij verkoop-/opvolgingstrajecten staat er verder een <strong>LoI-checklist</strong> in ("leg de kern-economics vroeg vast"): 15 punten die de dealwaarde bepalen — koopsom-aanpassingsmechanisme (locked box of completion accounts), exclusiviteit, reps &amp; warranties-kader, W&amp;I-verzekering, MAC-clausule, opschortende voorwaarden, non-concurrentie, retentie sleutelpersonen, behandeling overtollige liquiditeiten, kostenverdeling, geschillenregeling. Per punt ziet u of dit voorstel het al dekt ("gedekt"/"deels") of dat u het nog expliciet in de LoI moet vastleggen ("leg vast in LoI"). De gedachte: onderhandel de LoI alsof het de SPA is — wie een punt pas in de koopovereenkomst regelt, geeft onderhandelruimte weg. Dit is een aandachtspuntenlijst, géén juridisch advies; de reps &amp; warranties, MAC en opschortende voorwaarden werkt u met een jurist uit. Voert u parallel aan dít traject nog een of meer <strong>gekoppelde trajecten</strong> voor dezelfde verkoper (met andere kopers)? Dan kunt u via <strong>Biedingen vergelijken</strong> een Deal Value Matrix opstellen: de koopsom en betaalstructuur worden per gekoppeld traject uit het laatste Dealvoorstel geladen, u vult per bod nog vier inschattingen aan (aantal opschortende voorwaarden, financieringszekerheid, weken tot closing, strategische fit) en het platform zet de biedingen naast elkaar op een gewogen score (prijs 30% / zekerheid cash 25% / deal-zekerheid 20% / strategische fit 15% / timing 10%). Cash + escrow + earn-out horen ~100% van de koopsom te zijn (rode controleregel als dat afwijkt); behouden belang is géén betaling van de koper en telt niet mee in die check — het staat als eigen euro-regel (koopsom ÷ verkocht belang% × behouden belang%, op de hele onderneming), en bij een ongeldig percentage (100% of meer, of negatief) toont die regel "n.v.t." met een controleregel. Liggen de koopsommen van twee biedingen een factor >3 uiteen, dan waarschuwt de matrix dat je vermoedelijk ongelijke grootheden vergelijkt. De matrix <em>ordent</em>, hij kiest niet: de weging is vast (prijs 30% / zekerheid cash 25% / deal-zekerheid 20% / strategische fit 15% / timing 10%) — weeg de assen zelf tegen de prioriteiten van de verkoper, want een andere weging kan een andere volgorde geven. Koppelen gebeurt bij het aanmaken van een traject; de koperstrajecten blijven volledig gescheiden (elke koper ziet alleen het eigen traject). Daarnaast kunt u optioneel extra methodes meenemen, elk als kruiscontrole naast de hoofdwaardering, niet als vervanging: <strong>DCF</strong> (contante waarde van de toekomstige vrije kasstromen vóór financieringseffecten, verdisconteerd tegen de WACC/discontovoet, plus een terminal value voor de periode daarna — bij WACC lager dan of gelijk aan de groeivoet toont het scherm "n.v.t.", want dan is de formule wiskundig ongeldig); <strong>Intrinsieke waarde</strong> (rechtstreeks het ingevulde eigen vermogen — boekwaarde, geen correctie voor stille reserves of stille lasten); <strong>Liquidatiewaarde</strong> (wat overblijft bij gedwongen verkoop: inbare debiteuren/onderhanden werk minus liquidatiekosten minus schulden); <strong>Goodwill via de overwinstmethode</strong> (overwinst = genormaliseerde nettowinst minus een normrendement over het eigen vermogen; goodwill = die overwinst gedeeld door een kapitalisatievoet); <strong>Vendor loan</strong> (een echt rente-/aflossingsschema voor een eventuele verkoperslening, lineair of aflossingsvrij met een bullet-aflossing aan het einde — los van de bankfinanciering); <strong>Earn-out</strong> (een ander mechanisme dan de earn-up bij closing: hier wordt een deel van de koopsom zelf aangehouden en pas uitgekeerd in jaarlijkse tranches, gekoppeld aan een zelf ingestelde doelomzetgroei per jaar); <strong>Synergie-analyse</strong> (kosten- en omzetsynergieën die u zelf inschat, bouwen lineair op tot volledige realisatie en worden verdisconteerd tot een NPV); <strong>Scenarioanalyse</strong> (downside/base/upside: de EBITDA groeit door over de volledige horizon met een zelf ingestelde af- of opwaartse afwijking op de groeivoet); <strong>Aandelenruil</strong> (het deel bij closing wordt niet contant maar in nieuw uit te geven aandelen van de koper voldaan; de ruilverhouding wordt waarde-evenredig berekend, zonder controlepremie of -korting — dat is onderhandeling, geen berekening. Let op: de koper doorloopt op dit platform geen due diligence, dus de "waarde onderneming koper" is altijd een door u zelf ingevoerd, extern geverifieerd bedrag — nooit een door het platform berekende of geschatte waarde. Vult u ook het aantal bestaande aandelen van de koper in, dan toont het voorstel bovendien een indicatie van het aantal nieuw uit te geven aandelen. Dit is bewust de kleinere variant "aandelen-voor-aandelen binnen het bestaande koper/verkoper-model" — geen volledige juridische fusie: het gegenereerde document wijst er in een apart hoofdstuk op dat een échte fusie via Boek 2 BW een fundamenteel andere procedure is (fusievoorstel, KvK-deponering, wettelijke verzetstermijn crediteuren, notariële fusieakte) die dit platform niet doorloopt of vervangt — schakel daarvoor tijdig een notaris in). Belangrijk: bij alle percentages die u zelf invult (liquidatie-inbaarheid, goodwill-normrendement en -kapitalisatievoet, synergiebedragen, scenario-bandbreedte, earn-out-percentage en -doelgroei) vult het platform nooit zelf een waarde in als u het veld leeg laat — er wordt bewust geen branchenorm verzonnen. Laat u zo\'n veld leeg, dan blijft die specifieke uitkomst gewoon weg in plaats van een onbetrouwbaar cijfer te tonen. Is er al een Dealvoorstel verstuurd voor dit traject? Dan neemt de LoI-generatie de koopsom, multiple en escrow daaruit automatisch over (zichtbaar aan de melding boven het gegenereerde LoI-document) — zo blijven de cijfers naar de tegenpartij consistent. Cijfers in de AI-tekst van het Dealvoorstel (en van de interne bijlage) komen uitsluitend uit deze berekening; bevat de AI-tekst een ander cijfer, dan wordt de tekst geweigerd, wordt er niets overgenomen en kunt u opnieuw genereren.')
    + stap('3b','Kolommenbalans en exploitatieoverzicht','In de fase Financieel leest u of de verkoper per afgesloten boekjaar een kolommenbalans in (CSV of Excel). Het platform deelt elke grootboekrekening in een vaste indeling in en berekent het exploitatieoverzicht (omzet, brutomarge, kosten per soort, EBITDA, EBIT, resultaat) plus werkkapitaal en netto schuld (langlopende schulden min liquide middelen). Is een rekening niet eenduidig in te delen, dan blijft die op "Kies categorie" staan en wijst u hem zelf toe; het platform gokt nooit. Pas als alle rekeningen zijn ingedeeld en debet en credit sluiten, staat het jaar op Gereed en gebruikt het informatiememorandum de cijfers van de laatste drie gereed jaren. Staat de kolommenbalans al in het dossier omdat u hem met de andere documenten heeft geüpload, dan ziet u hem bovenaan het blok onder In het dossier gevonden. Controleer het boekjaar (voorgesteld uit de bestandsnaam) en kies Inlezen als kolommenbalans; opnieuw uploaden is niet nodig.')
    + stap('3c','Normalisaties, prognose en kerncijfers','Onder de kolommenbalans staat de aansluiting per boekjaar: gerapporteerde EBITDA, goedgekeurde normalisaties en genormaliseerde EBITDA, met brutomarge, EBITDA-marge, omzetgroei en (als u de fte per jaar invult) omzet en EBITDA per fte. Met "Voorstellen van KVM ophalen" signaleert het platform rekeningen die op eenmalige of niet-operationele kosten wijzen; u of de verkoper kunnen ook zelf normalisaties voorstellen (bedrag als effect op de EBITDA, post, soort, bron, karakter, zekerheid, motivering en risico). Alleen wat u met motivering goedkeurt telt mee; afwijzen vraagt een korte beoordeling. Een prognose van maximaal twee jaren rekent vanaf het laatste gereed boekjaar met uw aannames (omzetgroei, personeel, overige kosten) en verschijnt pas na goedkeuring, als scenario, in het informatiememorandum; elke wijziging zet hem terug naar concept. In het Dealvoorstel kunt u de genormaliseerde EBITDA en een goedgekeurde prognose met één klik overnemen; dat gebeurt nooit automatisch. Het informatiememorandum krijgt een vaste sectie Financiële kerncijfers met dezelfde cijfers.')
    + stap('3d','Verdienmodel, klanten en tarieven','In de fase Commercieel legt u of de verkoper het verdienmodel en de facturatiewijze vast en leest u een factuur- of omzetoverzicht in (CSV of Excel) met per regel minimaal klant, factuurdatum en bedrag; werksoort, branche, groep, uren, standaardtarief en klant sinds zijn optioneel. Het platform bewaart alleen totalen per relatie en toont per boekjaar het aantal unieke factuurrelaties, de concentratie (grootste relatie, top 5 en top 10), de omzetklassen, de relatieduur, de spreiding naar branche en de omzet per werksoort met gerealiseerd tegenover standaard uurtarief. Ook ziet u of de gefactureerde omzet aansluit op de omzet uit de kolommenbalans, en de debiteuren- en onderhanden-werkdagen uit de kolommenbalans. Een regel met een onleesbare datum of een dubbelzinnig bedrag laat het hele bestand weigeren, zodat er nooit half ingelezen cijfers ontstaan. In het memorandum verschijnen klanten alleen geanonimiseerd (Klant 1, Klant 2, met branche en aandeel).')
    + stap('3e','Personeel, huisvesting en IT','In de fase Partners &amp; personeel leest u of de verkoper een personeelsoverzicht in (CSV of Excel) met per medewerker minimaal functie en fte; geboortejaar, datum in dienst, contractvorm, loonkosten, kwalificatie en partner zijn optioneel. Namen en BSN worden niet gelezen of bewaard: het platform slaat alleen totalen op (aantallen, fte, leeftijds- en dienstjarenklassen, contractvormen) en toont gemiddelden en loonkosten alleen voor groepen van minimaal drie personen. In de fase Juridisch &amp; fiscaal legt u per locatie de plaats, oppervlakte, werkplekken, huur of eigendom, huurlasten en einddatum van het huurcontract vast en koppelt u het huurcontract en foto\'s uit de dossierdocumenten; contracten die binnen 24 maanden aflopen worden gemarkeerd. In de fase IT &amp; systemen legt u per systeem de categorie, leverancier, hosting, de overdraagbaarheid van de licentie, het contracteinde en de kosten vast; het platform toont de IT-kosten als percentage van de omzet en markeert niet-overdraagbare licenties en aflopende contracten. In het memorandum verschijnen alleen deze totalen, zonder namen of adressen.')
    + stap('4a','Transactievorm en scenario\'s','Leg eerst het doel van het traject vast: verkoop, fusie, overdracht van een belang of nog niet bekend. Het informatiememorandum gebruikt daarna de passende woorden, bijvoorbeeld fusiepartner en combinatie in plaats van koper en verkoop. In de fase Strategisch &amp; markt ziet u de oorspronkelijke voorkeur van de verkoper voor de transactievorm (alleen lezen). Daaronder legt u uw eigen advies vast, met een motivering, plus maximaal vijf scenario\'s. Wijzigingen worden automatisch opgeslagen; bij onvolledige invoer krijgt u een melding als u de fase verlaat. Per scenario geeft u het verkochte belang, de verdeling van de koopprijs over direct, earn-out, vendor loan en gespreid (samen 100%) en een eventueel behouden belang op. In het Dealvoorstel staat onder de opbrengst-brug dan een tabel "Transactiescenario\'s" die per scenario de ondernemingswaarde, aandelenwaarde, contante opbrengst bij closing, uitgestelde betaling, earn-out, vendor loan en behouden belang toont. Wijzigt de verkoper tegelijk zijn voorkeur, dan krijgt u een melding en blijft uw invoer staan.')
    + stap('11c','Verkopersreview van het informatiememorandum','Onder het verkoopmemorandum staat de sectie Verkopersreview. Sla het concept op en klik op "Concept delen met de verkoper"; de verkoper krijgt een e-mail en ziet de gedeelde versie in het eigen dossier. Per opmerking legt u vast of u die accepteert, deels overneemt, niet overneemt (met motivering), om informatie vraagt of als verwerkt markeert. Verwerk de aanpassingen in de tekst, sla op en klik op "Ter goedkeuring aanbieden" zodra er geen opmerkingen meer openstaan. Na het akkoord van de verkoper op die versie kunt u het memorandum definitief vaststellen. Wijzigt u de tekst na het akkoord, dan vervalt het akkoord en biedt u de nieuwe versie opnieuw aan. Versturen naar een geïnteresseerde partij kan alleen nadat die partij de NDA via het platform heeft ondertekend.')
    + stap('11d','Feiten uit de bron, opmaak naar keuze','In het informatiememorandum kunt u de tekst vrij herschrijven, hoofdstukken verplaatsen en secties weglaten. De secties Financiële kerncijfers, Kerngegevens klanten en verdienmodel en Kerngegevens organisatie, huisvesting en IT komen rechtstreeks uit de brongegevens (kolommenbalans, normalisaties, factuur-, personeels-, huisvestings- en IT-gegevens): die kunt u weglaten, maar niet inhoudelijk aanpassen. Klopt een cijfer niet, corrigeer het dan bij de bron en klik op "Kerngegevens vernieuwen"; de verkoper geeft daarna opnieuw akkoord. Bij definitief vaststellen en bij versturen controleert het platform of de kerngegevens nog actueel zijn en of alle bedragen, percentages en aantallen in de tekst herleidbaar zijn tot de brongegevens; zo niet, dan ziet u welke cijfers het betreft en kunt u niet vaststellen of versturen. Met "PDF zoals de koper hem ontvangt" bekijkt u het memorandum met voorblad, disclaimer, inhoudsopgave, grafieken uit de brongegevens en uw huisstijl. Versturen aan een koper kan alleen met het definitief vastgestelde memorandum en een geldig ondertekende NDA. Na het genereren toont het platform alleen voor u een redactionele controle: zinnen waarin een veldwaarde letterlijk is overgenomen of die herhaald worden. Pas die aan voordat u vaststelt.')
    + stap('11h','Financieel overzicht in één oogopslag','Direct na de managementsamenvatting staat het financieel overzicht in één oogopslag: netto-omzet, omzetgroei, EBITDA en marge, genormaliseerde EBITDA en marge, EBIT, resultaat vóór belastingen en, waar bekend, het aantal fte over drie boekjaren en twee prognosejaren, in € x 1.000. Prognosejaren (met een P, zoals 2026P) staan apart gekleurd en verschijnen alleen na goedkeuring van de prognose; ze zijn berekend vanaf de genormaliseerde cijfers van het laatste boekjaar, die in de prognosetabel als eerste kolom staan. Daaronder staan drie grafieken: omzet, EBITDA en genormaliseerde EBITDA, en de EBITDA-marge. Alles komt uit dezelfde brongegevens als de financiële kerncijfers. Sluiten de cijfers ergens niet aan, dan meldt het platform dat en kunt u het memorandum niet definitief vaststellen of versturen tot de bron is gecorrigeerd.')
    + stap('11i','Gelijktijdig werken aan hetzelfde dossier','Werken twee mensen tegelijk aan hetzelfde dossier, of staat het dossier in twee vensters open, dan overschrijft een opslag nooit ongemerkt een nieuwere waarde van een ander. Heeft iemand anders intussen hetzelfde veld gewijzigd, dan wordt uw wijziging niet opgeslagen en toont het scherm de actuele waarde met een melding; controleer die waarde en voer uw wijziging zo nodig opnieuw in. Velden die u niet zelf heeft aangepast, nemen automatisch de nieuwste waarde over. Voor de checklist en de notities van een fase geldt hetzelfde: heeft een ander die intussen gewijzigd terwijl u ze ook aanpaste, dan wordt uw versie niet opgeslagen en toont het scherm de versie van de ander. Uw eigen notitietekst blijft onder de notitie staan; u kiest zelf of u die terugzet of de versie van de ander houdt. Vinkjes zet u zo nodig opnieuw.')
    + stap('11j','Toekomstbestendigheid en schaalbaarheid (accountants- en administratiekantoren)','Bij een accountants- of administratiekantoor vul je in de fasen Klanten &amp; commercieel en IT &amp; automatisering de vragen in over de verdeling van de omzet over compliance en advies, handmatige verwerking, vaste werkwijzen, koppelingen, digitale klantdata en AI-gebruik. Geef per verdeling aan of het een feit uit de administratie is of een schatting. In Analyse en waardering ziet de begeleider per onderwerp de waarden met hun soort (feit, schatting, berekend of scenario), hoe volledig de gegevens zijn en een mogelijke richting voor de waardering. Die richting wordt nooit automatisch toegepast op de multiple of de waardering. Bij te weinig gegevens volgt geen uitkomst. Tellen de percentages samen op tot meer dan 100%, dan volgt een melding in plaats van een uitkomst. De begeleider legt vast dat de analyse is beoordeeld en of die in het informatiememorandum mag; pas daarna komt er een hoofdstuk Toekomstbestendigheid en schaalbaarheid in het memorandum, met feiten en schattingen en zonder waardeoordeel.')
    + stap('11k','Beveiliging en continuïteit','Een overzicht van waar je gegevens staan, welke leveranciers het platform gebruikt en hun onafhankelijke certificeringen, wat het platform zelf doet om je dossier te beschermen en wat er gebeurt bij een storing, staat op de pagina <a href="/platform/beveiliging-en-gegevens" target="_blank" rel="noopener">Beveiliging &amp; continuïteit</a>. Begeleiders vinden die ook onderaan het menu links.')
    + stap('11e','Beeldmateriaal in het informatiememorandum','In de fase Strategisch &amp; markt uploaden u en de verkoper foto\'s van het pand, het interieur, het team, de directie, de regio of de activiteiten, met een bijschrift. Kies bij elke foto de herkomst: een eigen foto van de onderneming, een sfeerbeeld of een illustratie. Een sfeerbeeld of illustratie krijgt in het memorandum altijd die vermelding, met bron en naamsvermelding, en wordt nooit als foto van de onderneming gepresenteerd; daarvoor zijn bron en licentie verplicht. Een eigen foto komt pas in het memorandum als bevestigd is dat de rechten en, bij herkenbare personen, hun toestemming geregeld zijn, en u de foto voor het memorandum hebt goedgekeurd. U kiest ook de coverfoto, de volgorde en het focuspunt van de uitsnede. Het platform plaatst de foto\'s bij het passende hoofdstuk, verkleint ze voor een compacte PDF en houdt ze privé. Zonder geschikte foto\'s krijgt het memorandum een nette beeldloze opmaak.')
    + stap('11f','Overeenkomsten en juridische aandachtspunten','In de fase Juridisch &amp; fiscaal leggen u en de verkoper de belangrijke overeenkomsten vast: soort, een korte omschrijving zonder namen van de wederpartij, looptijd, opzegtermijn, change of control, exclusiviteit en jaarwaarde. Daaronder staan de juridische aandachtspunten, zoals een geschil, een fiscaal punt, een vergunning of een garantie, met status en eventueel het geschatte financiële belang. Per regel beslist u of die in het informatiememorandum komt; alleen die regels verschijnen in het memorandum, als tabel met overeenkomsten en een lijst aandachtspunten. Past de verkoper een opgenomen regel aan, dan moet u die opnieuw goedkeuren. Aandachtspunten die u niet opneemt, blijven intern; bij het genereren van het memorandum ziet u hoeveel dat er zijn, zodat u ze in het due-diligenceonderzoek kunt bespreken.')
    + stap('11g','Kolommenbalans als bijlage bij het memorandum','Onder het memorandum kiest u welke kolommenbalansen als bijlage achter het informatiememorandum komen. Alleen een kolommenbalans die gereed is (debet en credit sluiten en alle rekeningen zijn ingedeeld) kan mee. De bijlage wordt bij elke PDF opnieuw uit de aangeleverde kolommenbalans opgebouwd, staat op een eigen pagina achteraan en verschijnt in de inhoudsopgave. Na het definitief vaststellen ligt de keuze vast; wijzigen kan via een nieuwe conceptversie.')
    + stap('4b','Risicoraamwerk (SWOT/PESTEL/Porter)','Genereert op basis van de al ingevulde DD-data en eerdere AI-beoordelingen een strategisch raamwerk: SWOT (sterktes/zwaktes/kansen/bedreigingen), PESTEL (politiek/economisch/sociaal/technologisch/ecologisch/juridisch) en een beknopte Porter\'s Five Forces-inschatting. Puur interne analyse — nooit voor verkoper of koper zichtbaar, en niet gekoppeld aan de Contracten-module (het is geen document dat naar een tegenpartij gaat). Is de beschikbare DD-data nog te dun voor een onderbouwd punt, dan benoemt het raamwerk dat expliciet in plaats van een aanname te verzinnen.')
    + stap('4c','Consistentie tussen documenten','In het dashboard, boven "Due diligence voortgang", staat het blok "🔍 Consistentie tussen documenten". Met "Documenten controleren" vergelijkt het platform 7 vaste documentparen binnen het dossier: omzet jaarrekening vs. verkoopmemorandum/teaser, werknemerslijst vs. loonadministratie, aandeelhoudersregister vs. UBO, fiscale eenheid vs. organogram, rekening-courant vs. koopprijsmechanisme, pensioen/bonus vs. SPA-garanties, en EBITDA-normalisaties vs. grootboek. Per paar krijgt u: consistent, afwijking of onvoldoende data — bij een afwijking de twee waarden met documentnaam, pagina en een letterlijk citaat uit elk stuk. Het platform beoordeelt <strong>nooit</strong> welke waarde de juiste is; dat is aan u. Een afwijking die verklaarbaar is (bijv. een verschil dat in een toelichting staat) vinkt u af met een notitie; hij blijft dan zichtbaar maar ingeklapt. De check blokkeert niets — hij waarschuwt alleen. Zijn er documenten bijgekomen sinds de laatste controle, dan meldt het blok dat. Voor deze check zijn minimaal twee documenten in het dossier nodig.')
    + stap(5,'Koper-fit strategie','Leg vast waarom de koper overnames zoekt en welke criteria daarbij horen (omzet/EBITDA-marge/FTE-drempels, sector/regio, vrije strategische tekst). Het systeem beoordeelt de verkoper hier expliciet tegen — harde cijfers worden automatisch getoetst, vrije tekst wordt door de AI uitsluitend geciteerd, nooit zelf beoordeeld. Alleen zichtbaar voor u, nooit voor de verkoper.')
    + stap(6,'Groepsstructuur beheren','Registreer entiteiten (holding + werkmaatschappijen) zodat documenten er correct aan gekoppeld worden en groepscijfers automatisch worden opgeteld. Wijkt een aangeleverd of handmatig ingevuld groepscijfer materieel af van de som van de entiteiten, dan toont het scherm (alleen voor u als begeleider) een keuze per veld: de som van de entiteiten overnemen, of het aangeleverde cijfer behouden. Zo wint een verkeerd cijfer nooit stilzwijgend.')
    + stap(7,'Partners / eigenaren beheren','Deze sectie past haar terminologie aan de sector aan — "partners" bij een accountants-/advieskantoor, "maten / praktijkhouders" bij een zorgpraktijk, "eigenaren / DGA" bij het mkb, "founders" bij een softwarebedrijf. Registreer ze bij naam (in plaats van per entiteit los leeftijd/veranderbereidheid in te vullen) en koppel elke persoon aan de entiteit(en) waar hij/zij aan verbonden is. Zo voorkomt u dubbele vragen over dezelfde persoon en ziet u meteen wie voor meerdere onderdelen omzet draait. Bij "omzet" wordt bewust gevraagd naar de omzet die aan de partner hangt inclusief onderliggend team — dat is de omzet die bij vertrek van de partner risico loopt, niet alleen zijn/haar eigen productie. De fase "Partners &amp; personeel" vraagt daarnaast expliciet naar het tweede echelon (de managementlaag die de onderneming ook zonder de eigenaar draaiend houdt), de key-person-afhankelijkheid (welk deel van de omzet of klantrelaties aan één persoon hangt) en — in fase 2 — de aanblijf-/retentieafspraken voor management.')
    + stap(8,'Gefaseerde koper-toegang','Via het koper-toegangsscherm bepaalt u per DD-categorie of en wanneer de koper die mag inzien. De koper ziet alleen de categorieën die u aanvinkt; staat er niets aangevinkt, dan ziet de koper nog geen dossierinhoud. De knop "Koper toegang geven" op het startscherm opent dezelfde keuze. De koper krijgt de naam van de onderneming en de aangevinkte categorieën pas te zien als de geheimhoudingsverklaring geldig is ondertekend: door de koper zelf op het platform, via Signhost, of met een ondertekend bestand dat bij het tekenen wordt geüpload. Een alleen ingevulde naam is niet genoeg; u kunt de categorieën wel alvast vastleggen.')
    + stap(9,'Informatieverzoeken en Q&amp;A','Stuur gerichte informatieverzoeken naar de verkoper per fase, en beheer het Q&amp;A-verkeer tussen koper en verkoper. Bij elke vraag kunt u een deadline zetten ("beantwoorden vóór") — een onbeantwoorde vraag na die datum krijgt een rode waarschuwing — en de vraag toewijzen aan een naam (bijv. uzelf of een collega) als geheugensteun. Na een antwoord blijft de vraag open voor een reactiedraad: koper en u kunnen erover doorpraten i.p.v. dat het bij één antwoord stopt.')
    + stap(10,'Wijzigingenlog','Elke wijziging, upload of verwijdering door de verkoper wordt gelogd met een meldingsbadge, zodat niets ongemerkt verandert.')
    + stap(11,'Meekijkers toevoegen','Wilt u een bank, accountant of andere aandrager beperkte, alleen-lezen inzage geven in dit traject? Bent u zelf beheerder, dan doet u dit bij dit traject in marilyn via de knop "Meekijkers"; bent u een externe adviseur, dan staat dezelfde functie bij dit traject in uw eigen adviseursportaal (adv.html), onder "Meekijkers". Bij het aanmaken bevestigt u expliciet dat er toestemming is van de opdrachtgever — zonder die bevestiging kan er geen toegangscode ontstaan. De meekijker moet vervolgens zelf een vertrouwelijkheidsverklaring accepteren voordat hij iets te zien krijgt, en verkoper/koper zien in hun eigen dashboard altijd wie er meekijkt. Toegang is altijd alleen-lezen, beperkt tot één fase (of alles), en op elk moment intrekbaar.')
    + stap('11b','Teaser, verkoopmemorandum en matching (module "Marketing")','De <strong>teaser</strong> (anoniem, circa 200-250 woorden, geen bedrijfsnaam) en het <strong>verkoopmemorandum</strong> (uitgebreid, mét bedrijfsnaam; het concept mag u al vóór de NDA opstellen, versturen pas ná een ondertekende NDA) staan — indien de module actief is — gewoon als stappen tussen de andere documenten in de Documenten-flow, niet in een aparte sectie: de teaser vóór de NDA (dat is immers vóór er een koper is), het verkoopmemorandum ná de NDA. Beide zijn na genereren bewerkbaar; <strong>Opslaan</strong> bewaart de tekst bij het traject (later terug via "bekijken/bewerken", geen bestand-download) en met <strong>Print / PDF</strong> maakt u er een net opgemaakt document van om te versturen. De teaser krijgt geen CONCEPT-watermerk. Het verkoopmemorandum is eerst een <strong>concept</strong>: bovenaan staat "CONCEPT" met de status (gegenereerd/bewerkt), en Print / PDF krijgt het CONCEPT-watermerk plus de regel "Conceptversie — controleer de inhoud vóór verspreiding". Het verkoopmemorandum wordt altijd opgesteld met de gegevens die er zijn: onderdelen zonder gegevens worden weggelaten en het document noemt nooit wat er ontbreekt. Alleen u ziet boven de tekst welke onderdelen zijn weggelaten, zodat u die gericht kunt uitvragen. Pas als er nog helemaal geen gegevens zijn, wordt er niets gegenereerd. Print / PDF maakt een informatiememorandum met voorblad, inhoudsopgave, paginanummers en een disclaimer. <strong>Definitief vaststellen</strong> (sinds 14 okt 2026): sla eerst op, vul uw naam in, vink de bevestiging aan en klik "Definitief vaststellen". Alleen de opgeslagen tekst wordt vastgelegd; het platform toont pas "DEFINITIEF — versie N" als de server dat heeft bevestigd. Daarna is de tekst vergrendeld en komt Print / PDF zonder watermerk. Is de tekst intussen elders gewijzigd, dan wordt niets vastgesteld: uw tekst blijft staan en u klikt eerst "Opnieuw lezen" (uw eigen tekst blijft daarbij apart zichtbaar en kunt u terugzetten). Wilt u na vaststelling iets wijzigen, klik dan "Nieuwe conceptversie" en daarna Opslaan; de definitieve versie blijft bewaard en het nieuwe concept stelt u later opnieuw vast als versie N+1. Vaststellen is geen verzending en geen juridische goedkeuring. Zet u de teaser vervolgens op "beschikbaar voor matching" — dat doet u niet hier op mna.html, maar bij dit traject in uw eigen adviseursportaal (adv.html) onder "Matching-platform"; bent u zelf platformbeheerder, dan kan dit ook via marilyn — dan verschijnt het traject anoniem op het losstaande matching-platform, gefilterd op sector/regio/omzetklasse tegen de daar geregistreerde koper-zoekprofielen (geen AI, puur filtering). Toont een geïnteresseerde koper zich daar en meldt hij zich aan, dan gebeurt automatisch: (1) de koper krijgt direct zijn eigen inlogcode gemaild, (2) u ontvangt een melding met naam/e-mail van de koper en het bijbehorende matching-tarief, (3) het traject verdwijnt automatisch van de matching-pagina (er is nu immers een koper). Dit is <strong>geen automatische vervolgstap</strong> in de rest van het traject — de koper ziet op dat moment nog niets inhoudelijks. Wilt u doorgaan, dan stuurt u zelf de NDA, en geeft u pas ná ondertekening zelf de gewenste DD-fases vrij (stap 8 hierboven) — precies dezelfde bewuste stappen als bij elke andere koper.')
    + stap('11c','Kosten inzien','Bent u zelf beheerder, dan ziet u alle kosten (trajectfees, module-fees, matching-fees) van alle adviseurs in marilyn (tabblad "€ Tarieven"). Bent u een externe adviseur, dan ziet u uitsluitend uw eigen kosten via de knop "€ Kosten" in uw adviseursportaal (adv.html) — inclusief uw eigen matching-tarief, zodat u vooraf weet wat een geslaagde match kost.')
    + stap('11d','Dossier exporteren (module "Export &amp; rapportage")','Is deze module actief, dan staat bij dit traject in uw adviseursportaal (adv.html) een knop "Dossier downloaden" — een compleet tekstbestand met de due-diligence-gegevens, Q&amp;A, gespreksverslagen, documentenlijst en toegangslog van dit ene traject. Uitsluitend zichtbaar/bruikbaar voor de adviseur die dit traject zelf begeleidt, nooit voor een andere adviseur. Bent u zelf beheerder, dan gebruikt u hiervoor de bestaande exportknop bij dit traject in marilyn.')
    + stap(12,'Traject afsluiten en databewaring','Sluit het traject af zodra de deal (of het contact) definitief is beëindigd — dit is niet vrijblijvend: veertien dagen ná afsluiting wordt <strong>alle</strong> trajectdata definitief verwijderd (documenten, ingevulde velden, gesprekken, Q&amp;A, waardering — alles), op een minimale archiefregel na (trajectnaam, datum, betrokken partijen). Bij het afsluiten ontvangt u direct een link naar één ZIP-download met het complete dossier — download deze binnen veertien dagen als u iets wilt bewaren, want daarna is het echt weg. Heeft u een concrete reden om een dossier langer te bewaren (bijvoorbeeld een lopend of dreigend geschil, of een wettelijke bewaarplicht), dan kunt u <strong>schriftelijk</strong> vragen de bewaartermijn voor dat ene traject te verlengen tot maximaal 365 dagen (VOK Artikel 5); Bisschops Financing zet die termijn dan voor u. Voor zo\'n verlengd dossier geldt een opslagvergoeding per aangevangen maand per traject, boven de gratis termijn van veertien dagen, conform het geldende tarievenoverzicht (bent u een externe adviseur, dan ziet u het actuele tarief onder "&euro; Kosten" in uw adviseursportaal). Na afloop van de verlengde termijn (of zodra de reden vervalt) wordt alsnog alles verwijderd. Sluit u een traject niet zelf af, dan doet het platform dat automatisch na drie maanden zonder inhoudelijke activiteit (u ontvangt daarvoor eerst een waarschuwing met nog veertien dagen de tijd om te reageren) — zo blijft er nooit onnodig data staan.')
    + stap(13,'Kantoorwerkruimte: dashboard en OHW-overleg','In het adviseursportaal staat bovenaan een vaste navigatie: Dashboard en mandaten, OHW-overleg, KantoorCockpit en Kennisbank. Het dashboard begint met drie blokken: wat aandacht vraagt (mandaten met een oranje of rode status en de reden, en uw acties die over de deadline zijn), wat u moet beoordelen (een status die afwijkt van het voorstel, of een dossier dat niet meer actueel is) en wat er hierna gebeurt (uw open acties en het volgende overleg). In het OHW-overleg ziet u per mandaat de opdrachtgever, de adviseur, de fase, de status met de concrete oorzaak, de belangrijkste open actie, wat er sinds het vorige overleg is veranderd en de verwachte fee. Klik op een mandaat om acties toe te wijzen aan een collega (met eigenaar en deadline), besluiten vast te leggen en de status te beoordelen. Het systeem stelt de status voor op basis van vaste regels (blokkade is rood; achterstallige acties, ontbrekende informatie of een niet-actueel dossier zijn oranje). Wijkt u daarvan af, dan geeft u een reden; die blijft met de historie bewaard. Met Overleg afronden krijgt iedereen de eigen nieuwe acties op het dashboard. Een kantooreigenaar ziet alle mandaten van het kantoor, een collega alleen de eigen mandaten.')
    + stap(14,'KantoorCockpit, fee-afspraken en koppeling met uw financiële pakket','Leg per mandaat in het OHW-overleg de fee-afspraak met de opdrachtgever vast: retainer, succesfee (percentage met eventueel minimum, of een vast bedrag), de verwachte transactiewaarde en de verwachte closingmaand. De verwachte fee wordt alleen berekend als de gegevens compleet zijn; anders ziet u wat er ontbreekt. De KantoorCockpit (alleen voor de kantooreigenaar) toont per mandaat de verwachte fee, het boekhoudkundig OHW, wat is gefactureerd, ontvangen en wat nog openstaat, steeds met de bron. Gefactureerd, ontvangen en openstaand komen uit uw financiële pakket via een alleen-lezen koppeling: KVM leest debiteuren, facturen, creditnota\'s en betalingen en boekt niets. Elke debiteur koppelt u zelf aan een mandaat. Wat niet beschikbaar is, staat er als niet beschikbaar; er wordt niets geschat. Koppelingen met echte pakketten worden per kantoor geactiveerd zodra de toegang is geregeld; tot die tijd kunt u de werking bekijken met een simulatie op fictieve gegevens.')
    + stap(15,'Kennisbank','Leg werkinstructies, modellen, clausules, lessons learned, DD- en onderhandelingsinzichten en vragen aan collega\'s vast. Kennis over een specifiek dossier blijft vertrouwelijk bij dat mandaat. Wilt u iets kantoorbreed delen, dan herschrijft u het zonder klantgegevens en bevestigt u dat; het systeem controleert de tekst op namen uit het dossier, e-mailadressen, KvK-nummers, IBAN en telefoonnummers en weigert het delen zolang die erin staan. Het origineel blijft bij het dossier. Zoek op onderwerp, soort, transactietype en fase.')
  );

  html += secties[eigenRol];

  // Begrippenlijst + berekeningsuitleg — voor ELKE rol zichtbaar (Marcel, 31 augustus 2026:
  // "geen twijfel over hoe iets tot stand is gekomen", toegankelijk voor alle gebruikers).
  function term(t, d){
    return '<div data-hb-item style="margin-bottom:.7rem"><div style="font-weight:600;color:var(--head);font-size:13px">'+t+'</div>'
      +'<div style="font-size:13px;color:var(--mid);line-height:1.6">'+d+'</div></div>';
  }
  function rekenBlok(t, d){
    return '<div data-hb-item style="margin-bottom:1rem;padding-left:12px;border-left:3px solid var(--teal-bg)"><div style="font-weight:600;color:var(--head);font-size:13px;margin-bottom:.2rem">'+t+'</div>'
      +'<div style="font-size:13px;color:var(--mid);line-height:1.65">'+d+'</div></div>';
  }
  html += sectie('begrippen', '📖 Begrippenlijst', ''
    + '<div style="font-size:12px;color:var(--muted);margin-bottom:1rem">De termen die op het waarderings- en dealscherm en in het Dealvoorstel voorkomen, in gewone taal.</div>'
    + term('EBITDA', 'Winst vóór rente, belasting, afschrijvingen en amortisatie — een maat voor de operationele winstkracht, los van financiering en boekhoudkeuzes.')
    + term('Genormaliseerde EBITDA', 'De EBITDA gecorrigeerd voor eenmalige posten en, waar van toepassing, een marktconform ondernemersloon. Dit is de grondslag waarop de waardering rekent.')
    + term('Chat (het gespreksbolletje rechtsonder)', 'Verkoper en koper hebben elk hun eigen, gescheiden gesprek met u als begeleider — nooit met elkaar, en nooit zichtbaar voor de ander (5 sep 2026: dit was eerder één gedeeld gesprek, sindsdien gescheiden in twee kanalen). Als begeleider schakelt u bovenin de chat tussen "Verkoper" en "Koper" om het juiste gesprek te zien/beantwoorden. Bij de verkoper is dit gesprek gecombineerd met een AI-assistent die helpt bij het invullen van het formulier.')
    + term('EBITDA-multiple', 'De factor waarmee de (genormaliseerde) EBITDA wordt vermenigvuldigd om de ondernemingswaarde te schatten. Bijvoorbeeld: EBITDA €400.000 × 5,0 = ondernemingswaarde €2.000.000.')
    + term('Ondernemingswaarde (Enterprise Value, EV)', 'De waarde van de onderneming zélf — vóór aftrek van schuld en vóór verdeling over de aandeelhouders.')
    + term('Equity value', 'Wat er voor de aandeelhouders overblijft: ondernemingswaarde − netto schuld − debt-like items − werkkapitaalcorrectie − transactiekosten.')
    + term('Netto schuld', 'De rentedragende schulden van de onderneming minus de vrij beschikbare liquide middelen.')
    + term('Debt-like items', 'Verplichtingen die economisch als schuld tellen ook al staan ze niet als lening op de balans — bijvoorbeeld achterstallige belasting, een pensioentekort of een lopende claim.')
    + term('Werkkapitaalcorrectie', 'Een aanpassing op de koopsom als het werkkapitaal (voorraden + debiteuren − crediteuren) bij closing afwijkt van een vooraf afgesproken normniveau.')
    + term('Transactiekosten', 'Advies-, due-diligence- en notariskosten rond de deal. In de opbrengst-brug een aanname die de begeleider invult (standaard 2% van de ondernemingswaarde).')
    + term('Belang bij closing', 'Het percentage van de aandelen dat de koper nú koopt. De rest houdt de verkoper aan — zie "behouden belang".')
    + term('Cash bij closing', 'Het bedrag dat de verkoper op de closingdatum daadwerkelijk contant ontvangt (dus ná aftrek van escrow en een eventuele uitgestelde earn-out).')
    + term('Escrow', 'Een deel van de koopsom dat tijdelijk op een geblokkeerde (derdengeld)rekening blijft staan als zekerheid voor eventuele claims. Komt na een afgesproken periode vrij als er geen claims zijn.')
    + term('Earn-out', 'Een deel van de koopsom dat pas later wordt uitgekeerd, in jaarlijkse tranches, als vooraf afgesproken doelen (bijvoorbeeld omzet- of EBITDA-groei) worden gehaald. Prestatie-afhankelijk, dus onzeker.')
    + term('Earn-up', 'Een éénmalige extra betaling in het eerste jaar als de prognose meteen wordt gehaald. Een ander mechanisme dan de earn-out.')
    + term('Vendor loan (verkoperslening)', 'Een deel van de koopsom dat de verkoper als lening aan de koper verstrekt, met rente en een aflossingsschema. Geen contant geld bij closing, en met kredietrisico op de koper.')
    + term('Behouden belang / rollover', 'Het deel van de aandelen dat de verkoper aanhoudt. De waarde daarvan staat pas vast bij een volgende verkoop ("tweede exit") en hangt af van hoe de onderneming zich daarna ontwikkelt.')
    + term('Cliff-drempel', 'Het EBITDA-niveau waaronder de laagste (basis-)multiple geldt. Beschermt de koper: valt de winst fors tegen, dan zakt de prijs niet onbeperkt mee via de glijdende schaal, maar geldt vanaf de cliff de vaste ondergrens.')
    + term('DCF (discounted cash flow)', 'Een waarderingsmethode: de waarde is de contante waarde van alle verwachte toekomstige vrije kasstromen. Op dit platform alleen als kruiscontrole naast de multiple.')
    + term('WACC / discontovoet', 'Het rendementspercentage waarmee toekomstige kasstromen naar de waarde van vandaag worden teruggerekend. Hoger = toekomstige bedragen tellen minder zwaar mee.')
    + term('Terminal value', 'De restwaarde van alle kasstromen ná de expliciete prognoseperiode, in één bedrag samengevat.')
    + term('Intrinsieke waarde', 'De boekwaarde van het eigen vermogen — bezittingen minus schulden volgens de balans, zonder correctie voor stille reserves.')
    + term('Liquidatiewaarde', 'Wat er overblijft bij gedwongen verkoop van de bezittingen, minus liquidatiekosten en schulden. Meestal de ondergrens van de waarde.')
    + term('Goodwill (overwinstmethode)', 'De waarde van de winst die uitkomt bóven een normaal rendement op het eigen vermogen. Overwinst gedeeld door een kapitalisatievoet = goodwill.')
    + term('Synergie', 'Extra waarde die ontstaat doordat koper en verkoper sámen meer waard zijn dan apart (kostenbesparingen, extra omzet). Een inschatting, geen berekening uit de cijfers.')
    + term('ZOPA', 'Zone of possible agreement — de ruimte tussen wat de verkoper minimaal accepteert en de koper maximaal biedt. Bestaat er geen overlap, dan is er geen deal.')
    + term('BATNA', 'Best alternative to a negotiated agreement — het beste alternatief van de verkoper als déze deal niet doorgaat (zelfstandig doorgaan, later verkopen, een andere koper, enzovoort).')
    + term('Walk-awayprijs', 'De minimale opbrengst waaronder de verkoper beter af is met zijn BATNA. Onder die grens is het beter om weg te lopen dan te tekenen.')
    + term('LoI (Letter of Intent / intentieverklaring)', 'Het document waarin koper en verkoper de hoofdlijnen van de deal vastleggen vóór de definitieve koopovereenkomst. Meestal deels niet-bindend, maar in de praktijk bepalend voor de uitkomst.')
    + term('SPA (Sale and Purchase Agreement)', 'De definitieve, bindende koopovereenkomst waarin alle afspraken juridisch worden vastgelegd.')
    + term('Reps & warranties (verklaringen en garanties)', 'Toezeggingen van de verkoper over de toestand van de onderneming (geen verborgen schulden, contracten kloppen, enzovoort). Kloppen ze niet, dan kan de koper een claim indienen.')
    + term('MAC-clausule (material adverse change)', 'Een clausule die de koper een uitweg geeft als er tussen tekenen en closing iets ernstigs misgaat.')
    + term('Opschortende voorwaarden', 'Voorwaarden waaraan voldaan moet zijn vóórdat de deal daadwerkelijk doorgaat — bijvoorbeeld financiering rond, toestemmingen verkregen, sleutelmedewerkers blijven.')
    + term('Locked box vs. completion accounts', 'Twee manieren om de koopsom vast te zetten: locked box = op een vaste peildatum vóór closing, geen naverrekening; completion accounts = afrekenen op basis van de werkelijke cijfers bij closing.')
    + term('W&I-verzekering (warranty & indemnity)', 'Een verzekering die claims onder de garanties afdekt, zodat de verkoper na closing niet meer persoonlijk aansprakelijk is.')
    + term('IRR (internal rate of return)', 'Het jaarlijkse rendementspercentage van een investering over de hele looptijd.')
    + term('Multiple-on-money (MoM)', 'Hoe vaak het ingelegde geld terugkomt — bijvoorbeeld 2,5× betekent dat €1 inleg €2,50 oplevert.')
    + term('Ondernemersloon (maatschap / eenmanszaak)', 'Een marktconforme beloning voor de werkende eigenaren. Bij een maatschap wordt dit éérst van de winst afgetrokken; de multiple rekent op de winst dáárna, en er is geen VpB-correctie (de maten betalen inkomstenbelasting in box 1).')
  );
  html += sectie('berekeningen', '🧮 Hoe de berekeningen tot stand komen', ''
    + '<div style="font-size:12px;color:var(--muted);margin-bottom:1rem">Elk model stap voor stap. <strong>GOUDEN STANDAARD:</strong> bij twijfel of ontbrekende invoer vult het platform nooit zelf een waarde in — dan blijft die uitkomst gewoon weg, in plaats van een gok te tonen. Waar hieronder "aanname" staat, is dat een bewust door de begeleider ingevoerde waarde, geen berekende uitkomst.</div>'
    + rekenBlok('Waardering — multiple × grondslag (hoofdmethode)', 'Grondslag × gekozen multiple = ondernemingswaarde. De grondslag is de genormaliseerde EBITDA (bij een maatschap/eenmanszaak: de winst ná een marktconform ondernemersloon, zonder VpB-correctie). Sommige sectoren (zorg) gebruiken een <strong>omzet-multiple</strong> (praktijkwaarde) in plaats van een EBITDA-multiple — dan wordt de hele dealvoorstel-rekenkern (glijdende schaal, cliff-drempel, gevoeligheidstabel, ondernemingswaarde in de opbrengst-brug) op de <strong>omzet</strong> toegepast, niet op de EBITDA; het schuldafbouw-/DCF-model blijft wél op EBITDA rekenen omdat schuldcapaciteit EBITDA-gedreven is. Bij zorg schakelt dit automatisch om op basis van omvang: een kleine, eigenaar-gedreven solopraktijk (groeps-FTE tot en met 5) rekent op de omzet-multiple, een grotere praktijk of keten (boven de 5 FTE) rekent op een EBITDA-multiple — u hoeft hier zelf niets voor in te stellen, het platform leest het al ingevulde FTE-veld. De multiple beweegt mee met de gerealiseerde grondslag via een glijdende schaal: op of onder de cliff-drempel geldt de basis-multiple, op of boven de prognose de bovengrens, daartussen lineair geïnterpoleerd. Kent een sector geen onderbouwde multiple-range, dan toont het platform bewust géén waardering (melding "geen multiple-range voor deze sector") in plaats van een gegokte bandbreedte; vul dan in het Dealvoorstel handmatig een onderbouwde multiple in.')
    + rekenBlok('Waardetoerekening per belang en de earn-up', 'Het hoofdstuk "Waardetoerekening per belang en de earn-up" rekent de ondernemingswaarde op bewezen basis toe aan het koper-belang (ondernemingswaarde × belang%) en aan het behouden belang — <strong>vóór</strong> aftrek van netto schuld, debt-like items en transactiekosten. Dat is een waardering, <strong>niet</strong> de cash die de verkoper bij closing ontvangt (die staat in de opbrengst-brug hieronder). De earn-up is de extra toegerekende waarde bij volledige realisatie van de prognose: (prognose-EBITDA × bovengrens-multiple × belang%) − (bewezen EBITDA × basis-multiple × belang%). Ook de earn-up is een toegerekende waarde; in de onderhandelruimte wordt hij herrekend naar de equity/cash-basis van de verkoper met dezelfde EV→equity-verhouding als de rest van de deal.')
    + rekenBlok('Opbrengst-brug — van ondernemingswaarde naar geld in handen', 'Ondernemingswaarde − netto schuld doelwit − debt-like items − werkkapitaalcorrectie − transactiekosten (aanname, % van de ondernemingswaarde) = equity value (100%). Equity value × het verkochte belang = de tegenprestatie voor dat belang. Daarvan af: − escrow − een eventuele uitgestelde earn-out = cash bij closing. Tel je de verwachte vrijval van escrow en earn-out er weer bij op, dan kom je op de "verwachte gerealiseerde waarde" — dat is het optimistische scenario (alles komt binnen). De netto schuld is voorgevuld uit de balansvelden (kortlopende + langlopende schulden − liquide middelen) als die zijn ingevuld; debt-like items en de werkkapitaalcorrectie vult de begeleider zelf in. Let op: dit is een andere schuldpost dan de nieuwe acquisitiefinanciering waarmee het schuldafbouwmodel bij closing start (× bewezen EBITDA) — het doelwit wordt cash-and-debt-free overgenomen, dus die twee horen niet gelijk te zijn. Ligt de netto schuld bóven de ondernemingswaarde, dan is de equity value negatief; het voorstel toont dan een waarschuwing en zet de opbrengst voor de verkoper op €0 (niet op een negatief bedrag — een negatieve "cash bij closing" zou onterecht suggereren dat de verkoper moet bijstorten).')
    + rekenBlok('Onderhandelruimte (ZOPA trade-space)', 'Splitst de <strong>waardepositie van de verkoper</strong> op naar zekerheid en timing: zeker bij closing (contant), escrow (uitgesteld maar doorgaans zeker), voorwaardelijk (earn-out, de voorwaardelijke earn-up en een eventuele verkoperslening) en behouden belang (geen betaling van de koper — de waarde van het niet-verkochte deel, pas vast bij een tweede exit). Bouwt op de opbrengst-brug plus de earn-up; de earn-up wordt daarbij van EV-toerekening naar de equity/cash-basis van de verkoper herrekend. De som van de vier delen is exact "verkocht belang + earn-up (verkoper-basis) + behouden belang". Zolang er een earn-up bestaat, is de voorwaardelijke laag dus nooit 0.')
    + rekenBlok('BATNA & walk-away (alleen verkoperszijde)', 'Vergelijkt twee bedragen met de door de begeleider ingevoerde walk-awayprijs: (1) de zekere cash bij closing en (2) de totale tegenprestatie voor het verkochte belang (cash + escrow + uitgestelde earn-out). Ligt de zekere cash al boven de walk-away → oordeel BOVEN. Ligt alleen de totale tegenprestatie erboven (dus alleen mét volledige escrow en earn-out) → KRAP. Ligt ook die eronder → ONDER (dit bod niet accepteren zoals het nu ligt). Een eventuele voorwaardelijke earn-up staat er ter info bij maar telt bewust niet mee in het oordeel — die komt pas bij volledige realisatie van de prognose in beeld. Is de walk-awayprijs niet ingevuld, dan volgt er géén oordeel.')
    + rekenBlok('LoI-checklist ("onderhandel de LoI alsof het de SPA is")', 'Een vaste lijst van 15 kern-economics. Per punt bepaalt het platform de status: "gedekt" (dit Dealvoorstel legt het al vast — koopsom, betaalstructuur, escrow, en earn-out als die aanstaat), "deels" (het bedrag staat vast maar het mechanisme niet, of het bijbehorende DD-veld is gevuld) of "leg vast in LoI" (SPA-materie die je nú al moet kaderen). Geen juridisch advies — een aandachtspuntenlijst.')
    + rekenBlok('Bod-vergelijker (Deal Value Matrix)', 'Per bod worden de euro-bedragen rechtstreeks herrekend uit de ingevoerde percentages. <em>Cash bij closing</em>, <em>escrow</em> en <em>earn-out uitgesteld</em> zijn percentages van de koopsom (de waarde van het verkochte belang) en horen samen ~100% te zijn — wijkt dat af, dan verschijnt een rode controleregel. <em>Behouden belang</em> is géén betaling van de koper maar de waarde van het niet-verkochte deel; het wordt berekend op de héle onderneming (koopsom ÷ verkocht belang% × behouden belang%) en telt daarom niet mee in die ~100%-check. Daarna vijf scores van 0-100: <em>prijs</em> = koopsom t.o.v. het hoogste bod; <em>zekerheid cash</em> = cash bij closing / koopsom; <em>deal-zekerheid</em> = financieringszekerheid (eigen middelen / commitment brief / nog te regelen) gecombineerd met het aantal opschortende voorwaarden; <em>timing</em> = weken tot closing (26 weken telt als 0); <em>strategische fit</em> = de inschatting van de begeleider. Totaalscore = gewogen som: prijs 30% · zekerheid cash 25% · deal-zekerheid 20% · strategische fit 15% · timing 10%. Earn-out en behouden belang staan elk als eigen euro-regel in de tabel — ze worden bewust niet tot één "upside"-getal opgeteld (twee verschillende grondslagen). Bij een ongeldig percentage behouden belang (100% of meer, of negatief) toont de regel "Behouden belang" <em>n.v.t.</em> met een rode controleregel i.p.v. een berekend bedrag — er is dan geen verkocht belang om de koopsom aan toe te rekenen. Liggen de koopsommen van de biedingen een factor >3 uiteen, dan waarschuwt de matrix dat vermoedelijk ongelijke grootheden worden vergeleken (ander belang%, of voor een traject ontbreekt nog een dealvoorstel). De matrix ordent, hij kiest niet.')
    + rekenBlok('DCF — kruiscontrole', 'De contante waarde van een <strong>vereenvoudigde unlevered kasstroom</strong> (EBITDA − belasting − capex − werkkapitaalmutatie) over de horizon, plus een terminal value volgens Gordon Growth: kasstroom laatste jaar × (1 + terminale groeivoet) / (WACC − terminale groeivoet). Dit is bewust geen volledige FCFF: standaard wordt de belasting over de EBITDA berekend (conservatief — het belastingschild op afschrijvingen ontbreekt dan). Vult u in het Dealvoorstel een afschrijvings-% in, dan berekent de DCF de belasting over de EBIT. Verdisconteerd tegen de ingevoerde discontovoet (WACC). De tabel toont WACC en terminale groeivoet apart, plus per jaar de oprentingsfactor (1+r)ᵗ — de deler waarmee elke toekomstige kasstroom wordt teruggerekend (een echte disconteringsfactor is de inverse daarvan, kleiner dan 1). Alleen bedoeld als plausibiliteitscheck naast de multiple-waardering — niet als bevestiging dat die "klopt"; bij een kleine marge tussen WACC en groeivoet weegt de terminal value zwaar. Is de discontovoet lager dan of gelijk aan de groeivoet, dan is de formule wiskundig ongeldig en toont het scherm "n.v.t.".')
    + rekenBlok('Schuldafbouwmodel — earn-up-financiering', 'Het meerjarige schuldafbouwmodel start met de nieuwe acquisitiefinanciering (× bewezen EBITDA) en lost die af met de vrije kasstroom. Een earn-up-uitkering in jaar 1 drukt standaard vóór 100% op de bankschuld; in het Dealvoorstel kunt u dat aandeel instellen (de rest wordt verondersteld uit eigen middelen te komen). Bij een negatieve bewezen EBITDA worden capex en werkkapitaalmutatie op 0 gezet — een negatief percentage zou anders een onzinnige kasINstroom opleveren.')
    + rekenBlok('Management- & sleutelpersoonrisico', 'Een kwalitatieve laag/midden/hoog-indicatie, afgeleid uit vijf ingevulde velden (key-person-afhankelijkheid, tweede echelon, veranderbereidheid, retentieafspraken, opvolging). Raakt <strong>nooit</strong> de multiple of de waardering — het is een aandachtspunt voor de risicoparagraaf en het retentiepakket. Een leeg veld telt als "onbekend", niet als risicopunt; alleen expliciete informatie levert punten op. Bij te veel onbekende velden vervalt het oordeel.')
    + rekenBlok('Financiële ratio\'s', 'Solvabiliteit, ROE, ROA, current ratio, quick ratio (exclusief voorraad en onderhanden werk — die zitten wél in de current ratio), EBITDA-dekking schuldendienst (een vereenvoudigde dekkingsgraad EBITDA / (rente + aflossing), géén volwaardige DSCR) en netto schuld/EBITDA worden berekend uit de balansvelden in fase 2 van "Financieel". Elke ratio verschijnt alléén als de bijbehorende velden zijn ingevuld — ontbrekende of onleesbare invoer (tekst i.p.v. een getal) geeft geen 0%, die ratio blijft dan gewoon weg.')
  );
  html += '</div>';

  html += '<div style="font-size:11px;color:var(--muted);text-align:center;margin-top:1rem">Deze handleiding toont de stappen voor uw eigen rol plus een begrippenlijst en uitleg van de berekeningen, en wordt bijgehouden zodra het platform wijzigt. Met het zoekveld bovenaan filtert u de onderdelen op deze pagina op een zoekterm. Via de knop "Leg mij dit uit" bovenaan een scherm opent u deze handleiding direct bij de uitleg die bij dat scherm hoort. Vragen? Neem contact op met uw adviseur of platformbeheerder.</div>';
  html += '</div>';
  return html;
}

// Zoekfilter van de handleiding (productpunt 31). Puur client-side op de al gerenderde inhoud:
// per data-hb-item een hoofdletter- en accentongevoelige tekstmatch op textContent; een sectie
// zonder zichtbare items wordt verborgen. De zoekterm wordt nooit als HTML ingevoegd — de
// geen-treffer-melding is een vaste tekst via textContent. Geen netwerk, geen opslag.
function hbNormaliseer(s){
  return String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/\s+/g,' ').trim();
}
// Productpunt 31 (24 okt 2026): contextuele hulp. "Leg mij dit uit" opent de bestaande handleiding
// (al gefilterd op de eigen rol) en vult het zoekveld met een vast onderwerp voor het scherm waar de
// gebruiker vandaan komt. Onderwerpen zijn vaste waarden uit HB_UITLEG (nooit gebruikersinvoer).
var HB_UITLEG = { fase: 'document', begeleider: 'dashboard' };
function legUitKnop(scherm){
  if(!HB_UITLEG[scherm]) return '';
  return '<button class="btn-ghost btn-sm" data-leg-uit="'+scherm+'" onclick="legMijDitUit(\''+scherm+'\')" title="Uitleg bij dit scherm in de handleiding">&#10067; Leg mij dit uit</button>';
}
function legMijDitUit(scherm){
  var term = HB_UITLEG[scherm] || '';
  try { if(typeof saveCurrent==='function') saveCurrent(); } catch(e) {}
  S.screen = 'handleiding';
  renderApp();
  var veld = document.getElementById('hb-zoek');
  if(veld && term){ veld.value = term; hbZoek(veld); if(veld.focus) veld.focus(); }
}

function hbZoek(invoer){
  var root = invoer && invoer.closest ? invoer.closest('[data-hb-root]') : null;
  if(!root) return;
  var q = hbNormaliseer(invoer.value);
  var treffers = 0;
  var secties = root.querySelectorAll('[data-hb-sectie]');
  for(var i=0;i<secties.length;i++){
    var items = secties[i].querySelectorAll('[data-hb-item]');
    var zichtbaar = 0;
    for(var j=0;j<items.length;j++){
      var past = !q || hbNormaliseer(items[j].textContent).indexOf(q) !== -1;
      items[j].hidden = !past;
      if(past) zichtbaar++;
    }
    secties[i].hidden = !!q && !zichtbaar;
    treffers += zichtbaar;
  }
  var melding = root.querySelector('[data-hb-leeg]');
  if(melding){
    var geen = !!q && !treffers;
    melding.textContent = geen ? 'Geen onderdelen gevonden voor deze zoekterm.' : '';
    melding.hidden = !geen;
  }
}
